window.QUESTION_TOPICS = window.QUESTION_TOPICS || {};
window.QUESTION_TOPICS["content/06_tools_build_debug/06_ci.md"] = [{"id":"content/06_tools_build_debug/06_ci.md:e07d5d60c0dc42ce:1","question":"<p>(L1, T) Что такое CI?</p>\n","answer":"<p><strong>Ответ:</strong> Continuous Integration — частая интеграция изменений с автоматической сборкой и проверками общего состояния проекта.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.github.com/en/actions\">GitHub Actions documentation</a>; <a href=\"https://cmake.org/cmake/help/latest/manual/ctest.1.html\">CTest</a></p>\n","group":"L1","line":35},{"id":"content/06_tools_build_debug/06_ci.md:758f0c77ee9092c8:1","question":"<p>(L1, T) Что такое CD?</p>\n","answer":"<p><strong>Ответ:</strong> Continuous Delivery поддерживает готовность к выпуску; Continuous Deployment автоматически выпускает прошедшие проверки изменения.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.github.com/en/actions\">GitHub Actions documentation</a>; <a href=\"https://cmake.org/cmake/help/latest/manual/ctest.1.html\">CTest</a></p>\n","group":"L1","line":41},{"id":"content/06_tools_build_debug/06_ci.md:a18f29dbaff1ccf7:1","question":"<p>(L1, T) Зачем C/C++ проекту CI pipeline?</p>\n","answer":"<p><strong>Ответ:</strong> Проверять совместимость toolchain, dependencies, конфигураций и поведение кода до интеграции, а не на машине автора.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.github.com/en/actions\">GitHub Actions documentation</a>; <a href=\"https://cmake.org/cmake/help/latest/manual/ctest.1.html\">CTest</a></p>\n","group":"L1","line":47},{"id":"content/06_tools_build_debug/06_ci.md:f3523f0364996c44:1","question":"<p>(L1, T) Какие базовые стадии обычно есть в pipeline?</p>\n","answer":"<p><strong>Ответ:</strong> Checkout/setup → configure/build → tests/analysis → package; deploy добавляют по требованиям продукта.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.github.com/en/actions\">GitHub Actions documentation</a>; <a href=\"https://cmake.org/cmake/help/latest/manual/ctest.1.html\">CTest</a></p>\n","group":"L1","line":53},{"id":"content/06_tools_build_debug/06_ci.md:6c99ba5101572385:1","question":"<p>(L1, T) Почему недостаточно просто “чтобы код компилировался локально”?</p>\n","answer":"<p><strong>Ответ:</strong> Локально могут быть лишние dependencies, stale artifacts, иные flags и окружение; общий gate должен быть воспроизводимым.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.github.com/en/actions\">GitHub Actions documentation</a>; <a href=\"https://cmake.org/cmake/help/latest/manual/ctest.1.html\">CTest</a></p>\n","group":"L1","line":59},{"id":"content/06_tools_build_debug/06_ci.md:647292b4f4328267:1","question":"<p>(L1, T) Что обычно проверяется на этапе build?</p>\n","answer":"<p><strong>Ответ:</strong> Доступность dependencies, корректность configure, compilation и linking в выбранной конфигурации.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.github.com/en/actions\">GitHub Actions documentation</a>; <a href=\"https://cmake.org/cmake/help/latest/manual/ctest.1.html\">CTest</a></p>\n","group":"L1","line":65},{"id":"content/06_tools_build_debug/06_ci.md:411c00b88f3f463f:1","question":"<p>(L1, T) Что обычно проверяется на этапе test?</p>\n","answer":"<p><strong>Ответ:</strong> Ожидаемое поведение и regression scenarios; build success не проверяет runtime correctness.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.github.com/en/actions\">GitHub Actions documentation</a>; <a href=\"https://cmake.org/cmake/help/latest/manual/ctest.1.html\">CTest</a></p>\n","group":"L1","line":71},{"id":"content/06_tools_build_debug/06_ci.md:879546a253d90ecb:1","question":"<p>(L1, T) Что обычно проверяется на этапе lint?</p>\n","answer":"<p><strong>Ответ:</strong> Согласованные formatting/static rules и выбранные code quality checks; состав зависит от политики проекта.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.github.com/en/actions\">GitHub Actions documentation</a>; <a href=\"https://cmake.org/cmake/help/latest/manual/ctest.1.html\">CTest</a></p>\n","group":"L1","line":77},{"id":"content/06_tools_build_debug/06_ci.md:8cea8141e326bb90:1","question":"<p>(L1, P) Какие минимальные шаги ты бы добавил в CI для небольшого C++ проекта?</p>\n","answer":"<p><strong>Ответ:</strong> Clean checkout, pinned toolchain, CMake configure/build, CTest и проверка форматирования; сохранить failure logs.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.github.com/en/actions\">GitHub Actions documentation</a>; <a href=\"https://cmake.org/cmake/help/latest/manual/ctest.1.html\">CTest</a></p>\n","group":"L1","line":83},{"id":"content/06_tools_build_debug/06_ci.md:15b38e2932e78278:1","question":"<p>(L1, D) Почему pipeline может падать, если локально все “работает”?</p>\n","answer":"<p><strong>Ответ:</strong> Различаются compiler, dependency versions, filesystem, locale, permissions, ресурсы или скрытое локальное состояние.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.github.com/en/actions\">GitHub Actions documentation</a>; <a href=\"https://cmake.org/cmake/help/latest/manual/ctest.1.html\">CTest</a></p>\n","group":"L1","line":89},{"id":"content/06_tools_build_debug/06_ci.md:ff26b536e781c25c:1","question":"<p>(L2, T) Чем unit tests отличаются от integration tests в контексте CI?</p>\n","answer":"<p><strong>Ответ:</strong> Unit проверяет узкий компонент, integration — связи компонентов/систем; вторые обычно требуют дополнительных ресурсов и окружения.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.github.com/en/actions\">GitHub Actions documentation</a>; <a href=\"https://cmake.org/cmake/help/latest/manual/ctest.1.html\">CTest</a></p>\n","group":"L2","line":98},{"id":"content/06_tools_build_debug/06_ci.md:1caaf7a5cfc9f74f:1","question":"<p>(L2, T) Почему build, tests и linting лучше разделять на отдельные jobs?</p>\n","answer":"<p><strong>Ответ:</strong> Независимые jobs дают parallelism и понятный failure owner; зависимые тесты должны получать exact build artifacts.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.github.com/en/actions\">GitHub Actions documentation</a>; <a href=\"https://cmake.org/cmake/help/latest/manual/ctest.1.html\">CTest</a></p>\n","group":"L2","line":104},{"id":"content/06_tools_build_debug/06_ci.md:91a553d0634fc671:1","question":"<p>(L2, T) Что такое fail-fast pipeline?</p>\n","answer":"<p><strong>Ответ:</strong> Рано прекращает явно бесполезную работу после ошибки; в matrix может отменять оставшиеся jobs.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.github.com/en/actions\">GitHub Actions documentation</a>; <a href=\"https://cmake.org/cmake/help/latest/manual/ctest.1.html\">CTest</a></p>\n","group":"L2","line":110},{"id":"content/06_tools_build_debug/06_ci.md:a352ebe6e8874770:1","question":"<p>(L2, T) Когда fail-fast полезен, а когда мешает?</p>\n","answer":"<p><strong>Ответ:</strong> Экономит время после fatal ошибки, но может скрыть независимые failures, нужные для анализа platform matrix.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.github.com/en/actions\">GitHub Actions documentation</a>; <a href=\"https://cmake.org/cmake/help/latest/manual/ctest.1.html\">CTest</a></p>\n","group":"L2","line":116},{"id":"content/06_tools_build_debug/06_ci.md:b1dd85cc129b2eaa:1","question":"<p>(L2, P) Как организовать pipeline: configure → build → test?</p>\n","answer":"<p><strong>Ответ:</strong> <code>cmake -S . -B build</code>, <code>cmake --build build --parallel 2</code>, <code>ctest --test-dir build --output-on-failure</code>; ошибки не подавлять.</p>\n<p><strong>Пример:</strong> Linux shell steps, с отдельным build tree на конфигурацию:</p>\n<pre><code class=\"language-bash\">cmake -S . -B build-ci -DCMAKE_BUILD_TYPE=RelWithDebInfo -DCMAKE_EXPORT_COMPILE_COMMANDS=ON\ncmake --build build-ci --parallel 2\nctest --test-dir build-ci --output-on-failure --no-tests=error\n</code></pre>\n<p>BUILD_TYPE относится к single-config generators; для multi-config задают <code>--config</code>. <code>--no-tests=error</code> поддерживается CTest 3.26+ и предотвращает ложный успех пустого test suite.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.github.com/en/actions\">GitHub Actions documentation</a>; <a href=\"https://cmake.org/cmake/help/latest/manual/ctest.1.html\">CTest</a></p>\n","group":"L2","line":122},{"id":"content/06_tools_build_debug/06_ci.md:f108ceca19b44498:1","question":"<p>(L2, P) Как добавить линтер в pipeline?</p>\n","answer":"<p><strong>Ответ:</strong> Зафиксировать version/config и отдельным step запустить clang-tidy либо formatter check; определить exit-code policy.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.github.com/en/actions\">GitHub Actions documentation</a>; <a href=\"https://cmake.org/cmake/help/latest/manual/ctest.1.html\">CTest</a></p>\n","group":"L2","line":138},{"id":"content/06_tools_build_debug/06_ci.md:c3df93528b251a5a:1","question":"<p>(L2, D) Почему тесты проходят локально, но нестабильны в CI?</p>\n","answer":"<p><strong>Ответ:</strong> Меньше CPU, иные timing/order, ресурсы и изоляция проявляют races и shared-state assumptions.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.github.com/en/actions\">GitHub Actions documentation</a>; <a href=\"https://cmake.org/cmake/help/latest/manual/ctest.1.html\">CTest</a></p>\n","group":"L2","line":144},{"id":"content/06_tools_build_debug/06_ci.md:e8918c2e7bc49ed5:1","question":"<p>(L2, D) Какие причины flaky tests наиболее типичны для C/C++?</p>\n","answer":"<p><strong>Ответ:</strong> Data races, time-based sleeps, зависимость от test order, shared ports/files, UB и внешняя сеть.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.github.com/en/actions\">GitHub Actions documentation</a>; <a href=\"https://cmake.org/cmake/help/latest/manual/ctest.1.html\">CTest</a></p>\n","group":"L2","line":150},{"id":"content/06_tools_build_debug/06_ci.md:d29e045b8408a926:1","question":"<p>(L2, T) Почему environment parity важен для CI?</p>\n","answer":"<p><strong>Ответ:</strong> Близкое окружение уменьшает различия, которые мешают воспроизводить failures; дополнительные platforms всё равно проверяют отдельно.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.github.com/en/actions\">GitHub Actions documentation</a>; <a href=\"https://cmake.org/cmake/help/latest/manual/ctest.1.html\">CTest</a></p>\n","group":"L2","line":156},{"id":"content/06_tools_build_debug/06_ci.md:0c02857ea1eb6145:1","question":"<p>(L2, T) Что такое reproducible pipeline?</p>\n","answer":"<p><strong>Ответ:</strong> Pipeline с фиксированными inputs и описанным окружением, который можно повторить; это ещё не гарантирует bit-identical binaries.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.github.com/en/actions\">GitHub Actions documentation</a>; <a href=\"https://cmake.org/cmake/help/latest/manual/ctest.1.html\">CTest</a></p>\n","group":"L2","line":162},{"id":"content/06_tools_build_debug/06_ci.md:5087b90ff18ba16a:1","question":"<p>(L3, T) Как проектировать stages для большого C/C++ проекта?</p>\n","answer":"<p><strong>Ответ:</strong> Строить dependency DAG, отделять cheap gates от full matrix и передавать exact artifacts вместо случайных rebuilds.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.github.com/en/actions\">GitHub Actions documentation</a>; <a href=\"https://cmake.org/cmake/help/latest/manual/ctest.1.html\">CTest</a></p>\n","group":"L3","line":171},{"id":"content/06_tools_build_debug/06_ci.md:35dfa4aa033f5668:1","question":"<p>(L3, T) Когда делать matrix builds?</p>\n","answer":"<p><strong>Ответ:</strong> Когда продукт поддерживает несколько OS, architectures, compilers или options; выбирать комбинации по риску и стоимости.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.github.com/en/actions\">GitHub Actions documentation</a>; <a href=\"https://cmake.org/cmake/help/latest/manual/ctest.1.html\">CTest</a></p>\n","group":"L3","line":177},{"id":"content/06_tools_build_debug/06_ci.md:2b6c0d8176af7a62:1","question":"<p>(L3, T) Зачем проверять несколько компиляторов и несколько build types?</p>\n","answer":"<p><strong>Ответ:</strong> Разные компиляторы обнаруживают разные проблемы, optimization проявляет UB, debug облегчает диагностику.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.github.com/en/actions\">GitHub Actions documentation</a>; <a href=\"https://cmake.org/cmake/help/latest/manual/ctest.1.html\">CTest</a></p>\n","group":"L3","line":183},{"id":"content/06_tools_build_debug/06_ci.md:8cd58fb1f300d549:1","question":"<p>(L3, P) Как встроить sanitizer builds в pipeline?</p>\n","answer":"<p><strong>Ответ:</strong> Отдельные build directories и compile/link sanitizer flags; запускать ASan/UBSan и TSan в совместимых отдельных jobs.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.github.com/en/actions\">GitHub Actions documentation</a>; <a href=\"https://cmake.org/cmake/help/latest/manual/ctest.1.html\">CTest</a></p>\n","group":"L3","line":189},{"id":"content/06_tools_build_debug/06_ci.md:7e04cf04e7e70f9e:1","question":"<p>(L3, P) Как встроить static analysis в pipeline без чрезмерного slowdown?</p>\n","answer":"<p><strong>Ответ:</strong> Быстрые trusted checks на PR, cache конфигурации и full analysis по расписанию; generated/third-party paths исключать явно.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.github.com/en/actions\">GitHub Actions documentation</a>; <a href=\"https://cmake.org/cmake/help/latest/manual/ctest.1.html\">CTest</a></p>\n","group":"L3","line":195},{"id":"content/06_tools_build_debug/06_ci.md:6c75f3f1afade158:1","question":"<p>(L3, D) Почему pipeline медленный и как найти узкие места?</p>\n","answer":"<p><strong>Ответ:</strong> Измерить queue, setup, configure, compile, linking и tests отдельно; оптимизировать крупнейший critical path.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.github.com/en/actions\">GitHub Actions documentation</a>; <a href=\"https://cmake.org/cmake/help/latest/manual/ctest.1.html\">CTest</a></p>\n","group":"L3","line":201},{"id":"content/06_tools_build_debug/06_ci.md:986e7035417bc46a:1","question":"<p>(L3, D) Почему CI обнаруживает missing dependencies, которые не видны локально?</p>\n","answer":"<p><strong>Ответ:</strong> Clean runner не содержит случайных packages и старых generated headers; это выявляет незаявленные inputs.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.github.com/en/actions\">GitHub Actions documentation</a>; <a href=\"https://cmake.org/cmake/help/latest/manual/ctest.1.html\">CTest</a></p>\n","group":"L3","line":207},{"id":"content/06_tools_build_debug/06_ci.md:cd469ebe62870e11:1","question":"<p>(L3, T) Когда нужны nightly jobs, а не только per-commit jobs?</p>\n","answer":"<p><strong>Ответ:</strong> Для долгих stress/fuzz, полной matrix и глубокого анализа; критичные быстрые проверки должны оставаться на PR.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.github.com/en/actions\">GitHub Actions documentation</a>; <a href=\"https://cmake.org/cmake/help/latest/manual/ctest.1.html\">CTest</a></p>\n","group":"L3","line":213},{"id":"content/06_tools_build_debug/06_ci.md:0e8c207259192887:1","question":"<p>(L3, S) Как разделить “быстрые обязательные проверки” и “дорогие глубокие проверки”?</p>\n","answer":"<p><strong>Ответ:</strong> Разделить по времени, defect impact и supported configurations; nightly failures тоже должны иметь owner и срок реакции.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.github.com/en/actions\">GitHub Actions documentation</a>; <a href=\"https://cmake.org/cmake/help/latest/manual/ctest.1.html\">CTest</a></p>\n","group":"L3","line":219},{"id":"content/06_tools_build_debug/06_ci.md:d0cba3a162314efe:1","question":"<p>(L3, D) Как расследовать intermittent failures в C++ pipeline?</p>\n","answer":"<p><strong>Ответ:</strong> Сохранять exact inputs, logs, seed и environment; различать infrastructure, flaky test и product defect.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.github.com/en/actions\">GitHub Actions documentation</a>; <a href=\"https://cmake.org/cmake/help/latest/manual/ctest.1.html\">CTest</a></p>\n","group":"L3","line":225},{"id":"content/06_tools_build_debug/06_ci.md:30d86e615c75680f:1","question":"<p>(L4, S) Как спроектировать CI strategy для большого монорепозитория на C/C++?</p>\n","answer":"<p><strong>Ответ:</strong> Dependency-aware affected checks, общие templates, full periodic validation и владельцы каждого gate; не полагаться на path filters без graph.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.github.com/en/actions\">GitHub Actions documentation</a>; <a href=\"https://cmake.org/cmake/help/latest/manual/ctest.1.html\">CTest</a></p>\n","group":"L4","line":234},{"id":"content/06_tools_build_debug/06_ci.md:27481fc2acdce09a:1","question":"<p>(L4, S) Как выбрать quality gates, чтобы не убить velocity команды?</p>\n","answer":"<p><strong>Ответ:</strong> Блокировать reproducible high-signal defects; шумные проверки сначала стабилизировать или делать advisory с owner.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.github.com/en/actions\">GitHub Actions documentation</a>; <a href=\"https://cmake.org/cmake/help/latest/manual/ctest.1.html\">CTest</a></p>\n","group":"L4","line":240},{"id":"content/06_tools_build_debug/06_ci.md:f0ae6fba35674ea0:1","question":"<p>(L4, S) Как построить pipeline, который одновременно быстрый, надежный и воспроизводимый?</p>\n","answer":"<p><strong>Ответ:</strong> Pinned images/dependencies, isolated workspaces, correct caching, parallel DAG и сохранение diagnostic artifacts.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.github.com/en/actions\">GitHub Actions documentation</a>; <a href=\"https://cmake.org/cmake/help/latest/manual/ctest.1.html\">CTest</a></p>\n","group":"L4","line":246},{"id":"content/06_tools_build_debug/06_ci.md:b20df5f13c02185f:1","question":"<p>(L4, D) Как triage'ить постоянный поток CI failures в большой организации?</p>\n","answer":"<p><strong>Ответ:</strong> Классифицировать причины и frequency, назначать owners, устранять повторяющиеся flakes и infrastructure failures.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.github.com/en/actions\">GitHub Actions documentation</a>; <a href=\"https://cmake.org/cmake/help/latest/manual/ctest.1.html\">CTest</a></p>\n","group":"L4","line":252},{"id":"content/06_tools_build_debug/06_ci.md:78e1f8f4d96d4909:1","question":"<p>(L4, S) Как превратить CI из “формальной галочки” в реальный инженерный контроль качества?</p>\n","answer":"<p><strong>Ответ:</strong> Проверки должны соответствовать реальным defect classes, иметь прозрачный failure report и измеримую полезность.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.github.com/en/actions\">GitHub Actions documentation</a>; <a href=\"https://cmake.org/cmake/help/latest/manual/ctest.1.html\">CTest</a></p>\n","group":"L4","line":258},{"id":"content/06_tools_build_debug/06_ci.md:b5469a8ce6c66113:1","question":"<p>(L1, T) Что такое build cache?</p>\n","answer":"<p><strong>Ответ:</strong> Повторное использование результатов, вычисленных для эквивалентных inputs; корректность зависит от полноты ключа.</p>\n<p><strong>Источник:</strong> <a href=\"https://ccache.dev/manual/latest.html\">ccache manual</a>; <a href=\"https://docs.github.com/en/actions/using-workflows/caching-dependencies-to-speed-up-workflows\">GitHub: Caching dependencies</a></p>\n","group":"L1","line":269},{"id":"content/06_tools_build_debug/06_ci.md:aaae5cc53eff1049:1","question":"<p>(L1, T) Зачем кэшировать артефакты сборки?</p>\n","answer":"<p><strong>Ответ:</strong> Чтобы не повторять дорогую compilation/download работу при неизменных inputs.</p>\n<p><strong>Источник:</strong> <a href=\"https://ccache.dev/manual/latest.html\">ccache manual</a>; <a href=\"https://docs.github.com/en/actions/using-workflows/caching-dependencies-to-speed-up-workflows\">GitHub: Caching dependencies</a></p>\n","group":"L1","line":275},{"id":"content/06_tools_build_debug/06_ci.md:d44c3e559ea05734:1","question":"<p>(L1, T) Что обычно кэшируют в C/C++ pipeline?</p>\n","answer":"<p><strong>Ответ:</strong> Package downloads, compiler cache вроде ccache/sccache и outputs поддерживающей cache build system.</p>\n<p><strong>Источник:</strong> <a href=\"https://ccache.dev/manual/latest.html\">ccache manual</a>; <a href=\"https://docs.github.com/en/actions/using-workflows/caching-dependencies-to-speed-up-workflows\">GitHub: Caching dependencies</a></p>\n","group":"L1","line":281},{"id":"content/06_tools_build_debug/06_ci.md:3f8806c7432f27cf:1","question":"<p>(L1, T) Чем dependency cache отличается от artifact cache?</p>\n","answer":"<p><strong>Ответ:</strong> Dependency cache ускоряет получение inputs; artifact cache переиспользует outputs. Release artifacts требуют отдельной идентичности и хранения.</p>\n<p><strong>Источник:</strong> <a href=\"https://ccache.dev/manual/latest.html\">ccache manual</a>; <a href=\"https://docs.github.com/en/actions/using-workflows/caching-dependencies-to-speed-up-workflows\">GitHub: Caching dependencies</a></p>\n","group":"L1","line":287},{"id":"content/06_tools_build_debug/06_ci.md:73e6c8ab42a01a95:1","question":"<p>(L1, D) Почему без cache pipeline может быть слишком медленным?</p>\n","answer":"<p><strong>Ответ:</strong> Каждый job заново скачивает и компилирует одинаковые зависимости, даже если изменений почти нет.</p>\n<p><strong>Источник:</strong> <a href=\"https://ccache.dev/manual/latest.html\">ccache manual</a>; <a href=\"https://docs.github.com/en/actions/using-workflows/caching-dependencies-to-speed-up-workflows\">GitHub: Caching dependencies</a></p>\n","group":"L1","line":293},{"id":"content/06_tools_build_debug/06_ci.md:b255ab28bf81deab:1","question":"<p>(L2, T) Какие риски у build caching?</p>\n","answer":"<p><strong>Ответ:</strong> Неполные keys, stale outputs, несовместимые configs и cache poisoning; cache не должен быть необходим для correctness.</p>\n<p><strong>Источник:</strong> <a href=\"https://ccache.dev/manual/latest.html\">ccache manual</a>; <a href=\"https://docs.github.com/en/actions/using-workflows/caching-dependencies-to-speed-up-workflows\">GitHub: Caching dependencies</a></p>\n","group":"L2","line":302},{"id":"content/06_tools_build_debug/06_ci.md:81bec4acc0dad9a2:1","question":"<p>(L2, D) Почему cache может приводить к “ложно зеленым” pipeline?</p>\n","answer":"<p><strong>Ответ:</strong> Ошибочно переиспользует output, игнорируя изменённый header, generator, flag или dependency.</p>\n<p><strong>Источник:</strong> <a href=\"https://ccache.dev/manual/latest.html\">ccache manual</a>; <a href=\"https://docs.github.com/en/actions/using-workflows/caching-dependencies-to-speed-up-workflows\">GitHub: Caching dependencies</a></p>\n","group":"L2","line":308},{"id":"content/06_tools_build_debug/06_ci.md:0c246b19324de553:1","question":"<p>(L2, T) Что влияет на cache key?</p>\n","answer":"<p><strong>Ответ:</strong> Source/generated inputs, compiler/toolchain, platform, flags и dependency lockfiles; конкретный compiler cache учитывает часть автоматически.</p>\n<p><strong>Пример:</strong> Внешний cache scope: OS + target + compiler identity + dependency-lock hash + sanitizer/config. Это схема inputs, а не готовая строка key для любого cache backend.</p>\n<p><strong>Типичная ошибка:</strong> Один writable cache для release и untrusted PR, содержащий одновременно package downloads и готовые executables.</p>\n<p><strong>Источник:</strong> <a href=\"https://ccache.dev/manual/latest.html\">ccache manual</a>; <a href=\"https://docs.github.com/en/actions/using-workflows/caching-dependencies-to-speed-up-workflows\">GitHub: Caching dependencies</a></p>\n","group":"L2","line":314},{"id":"content/06_tools_build_debug/06_ci.md:db45b7a4239433c5:1","question":"<p>(L2, P) Какие директории обычно стоит кэшировать в CMake/Ninja проекте?</p>\n","answer":"<p><strong>Ответ:</strong> Compiler cache и package cache; перенос всего build tree рискован из-за absolute paths, generator state и toolchain mismatch.</p>\n<p><strong>Источник:</strong> <a href=\"https://ccache.dev/manual/latest.html\">ccache manual</a>; <a href=\"https://docs.github.com/en/actions/using-workflows/caching-dependencies-to-speed-up-workflows\">GitHub: Caching dependencies</a></p>\n","group":"L2","line":324},{"id":"content/06_tools_build_debug/06_ci.md:30e11d4719ff4f84:1","question":"<p>(L2, P) Как кэшировать зависимости package manager'а?</p>\n","answer":"<p><strong>Ответ:</strong> Использовать documented package-manager cache path и key от lockfile/platform/toolchain; не кэшировать credentials.</p>\n<p><strong>Источник:</strong> <a href=\"https://ccache.dev/manual/latest.html\">ccache manual</a>; <a href=\"https://docs.github.com/en/actions/using-workflows/caching-dependencies-to-speed-up-workflows\">GitHub: Caching dependencies</a></p>\n","group":"L2","line":330},{"id":"content/06_tools_build_debug/06_ci.md:7f898bb2fc54847e:1","question":"<p>(L2, D) Почему stale cache ломает сборку?</p>\n","answer":"<p><strong>Ответ:</strong> Старые outputs не соответствуют текущим inputs либо содержат state, который build graph не умеет инвалидировать.</p>\n<p><strong>Источник:</strong> <a href=\"https://ccache.dev/manual/latest.html\">ccache manual</a>; <a href=\"https://docs.github.com/en/actions/using-workflows/caching-dependencies-to-speed-up-workflows\">GitHub: Caching dependencies</a></p>\n","group":"L2","line":336},{"id":"content/06_tools_build_debug/06_ci.md:644cc87737b1c835:1","question":"<p>(L2, T) Когда лучше сохранять артефакты, а не кэш?</p>\n","answer":"<p><strong>Ответ:</strong> Когда нужен конкретный output данного run: binaries, symbols, packages и reports для downstream jobs или выпуска.</p>\n<p><strong>Источник:</strong> <a href=\"https://ccache.dev/manual/latest.html\">ccache manual</a>; <a href=\"https://docs.github.com/en/actions/using-workflows/caching-dependencies-to-speed-up-workflows\">GitHub: Caching dependencies</a></p>\n","group":"L2","line":342},{"id":"content/06_tools_build_debug/06_ci.md:75cbf73e05ad6d8b:1","question":"<p>(L2, D) Почему cache hit не гарантирует корректность результата?</p>\n","answer":"<p><strong>Ответ:</strong> Key может быть неполным, а cache entry повреждённым; periodic clean builds проверяют независимость от cache.</p>\n<p><strong>Источник:</strong> <a href=\"https://ccache.dev/manual/latest.html\">ccache manual</a>; <a href=\"https://docs.github.com/en/actions/using-workflows/caching-dependencies-to-speed-up-workflows\">GitHub: Caching dependencies</a></p>\n","group":"L2","line":348},{"id":"content/06_tools_build_debug/06_ci.md:e34e7ae12dbe250e:1","question":"<p>(L2, P) Как разделять cache между branch'ами и main?</p>\n","answer":"<p><strong>Ответ:</strong> Общий доверенный read baseline и отдельные write scopes для branches; untrusted jobs не должны менять release cache.</p>\n<p><strong>Источник:</strong> <a href=\"https://ccache.dev/manual/latest.html\">ccache manual</a>; <a href=\"https://docs.github.com/en/actions/using-workflows/caching-dependencies-to-speed-up-workflows\">GitHub: Caching dependencies</a></p>\n","group":"L2","line":354},{"id":"content/06_tools_build_debug/06_ci.md:7428ecaac25f6685:1","question":"<p>(L2, T) Почему compiler version должна участвовать в cache key?</p>\n","answer":"<p><strong>Ответ:</strong> Версия влияет на codegen, object format, diagnostics и ABI; одинаковый source не означает эквивалентный output.</p>\n<p><strong>Источник:</strong> <a href=\"https://ccache.dev/manual/latest.html\">ccache manual</a>; <a href=\"https://docs.github.com/en/actions/using-workflows/caching-dependencies-to-speed-up-workflows\">GitHub: Caching dependencies</a></p>\n","group":"L2","line":360},{"id":"content/06_tools_build_debug/06_ci.md:00960092404b0cd0:1","question":"<p>(L3, T) Что такое remote build cache?</p>\n","answer":"<p><strong>Ответ:</strong> Общее хранилище результатов сборки для нескольких workers, обычно адресуемое по digest inputs.</p>\n<p><strong>Источник:</strong> <a href=\"https://ccache.dev/manual/latest.html\">ccache manual</a>; <a href=\"https://docs.github.com/en/actions/using-workflows/caching-dependencies-to-speed-up-workflows\">GitHub: Caching dependencies</a></p>\n","group":"L3","line":369},{"id":"content/06_tools_build_debug/06_ci.md:4dca932545710cb9:1","question":"<p>(L3, T) Как cache взаимодействует с reproducibility?</p>\n","answer":"<p><strong>Ответ:</strong> Корректный cache сохраняет результат; reproducibility позволяет независимо проверить его пересборкой с теми же inputs.</p>\n<p><strong>Источник:</strong> <a href=\"https://ccache.dev/manual/latest.html\">ccache manual</a>; <a href=\"https://docs.github.com/en/actions/using-workflows/caching-dependencies-to-speed-up-workflows\">GitHub: Caching dependencies</a></p>\n","group":"L3","line":375},{"id":"content/06_tools_build_debug/06_ci.md:3f3ba95e3e7a7f37:1","question":"<p>(L3, D) Почему инкрементальная локальная логика не всегда переносится на CI cache?</p>\n","answer":"<p><strong>Ответ:</strong> CI меняет paths, workspace lifetime и toolchain; сохранённый локальный build tree может содержать скрытые machine-specific inputs.</p>\n<p><strong>Источник:</strong> <a href=\"https://ccache.dev/manual/latest.html\">ccache manual</a>; <a href=\"https://docs.github.com/en/actions/using-workflows/caching-dependencies-to-speed-up-workflows\">GitHub: Caching dependencies</a></p>\n","group":"L3","line":381},{"id":"content/06_tools_build_debug/06_ci.md:9706ddb71f22e4bb:1","question":"<p>(L3, P) Как проектировать ключи кэша для toolchain + dependencies + build config?</p>\n","answer":"<p><strong>Ответ:</strong> Включить image/toolchain identity, target, dependency lock hash и config; source keys делегировать compiler/build cache где возможно.</p>\n<p><strong>Источник:</strong> <a href=\"https://ccache.dev/manual/latest.html\">ccache manual</a>; <a href=\"https://docs.github.com/en/actions/using-workflows/caching-dependencies-to-speed-up-workflows\">GitHub: Caching dependencies</a></p>\n","group":"L3","line":387},{"id":"content/06_tools_build_debug/06_ci.md:5a768e58644ff61b:1","question":"<p>(L3, D) Почему LTO/sanitizer/debug/release сборки нельзя бездумно смешивать в одном cache?</p>\n","answer":"<p><strong>Ответ:</strong> Отличаются instrumentation, bitcode compatibility и runtime dependencies; cache должен различать все влияющие flags.</p>\n<p><strong>Источник:</strong> <a href=\"https://ccache.dev/manual/latest.html\">ccache manual</a>; <a href=\"https://docs.github.com/en/actions/using-workflows/caching-dependencies-to-speed-up-workflows\">GitHub: Caching dependencies</a></p>\n","group":"L3","line":393},{"id":"content/06_tools_build_debug/06_ci.md:7d00acf94742031f:1","question":"<p>(L3, D) Как понять, что cache экономит время, а не добавляет сложность?</p>\n","answer":"<p><strong>Ответ:</strong> Измерять restore/save time, hit rate, bytes и end-to-end duration; cache с дорогой передачей может не окупаться.</p>\n<p><strong>Источник:</strong> <a href=\"https://ccache.dev/manual/latest.html\">ccache manual</a>; <a href=\"https://docs.github.com/en/actions/using-workflows/caching-dependencies-to-speed-up-workflows\">GitHub: Caching dependencies</a></p>\n","group":"L3","line":399},{"id":"content/06_tools_build_debug/06_ci.md:d4d5c7ab0cd1b471:1","question":"<p>(L3, T) Какие артефакты стоит публиковать между stages вместо rebuild?</p>\n","answer":"<p><strong>Ответ:</strong> Проверяемый executable, shared libs, debug symbols и manifest; tests должны работать с этим же набором.</p>\n<p><strong>Источник:</strong> <a href=\"https://ccache.dev/manual/latest.html\">ccache manual</a>; <a href=\"https://docs.github.com/en/actions/using-workflows/caching-dependencies-to-speed-up-workflows\">GitHub: Caching dependencies</a></p>\n","group":"L3","line":405},{"id":"content/06_tools_build_debug/06_ci.md:80f1f53b162c5fbe:1","question":"<p>(L3, D) Как расследовать “невоспроизводимые” баги, связанные с reused artifacts?</p>\n","answer":"<p><strong>Ответ:</strong> Сверить hashes/manifests, run IDs и keys; повторить clean build и найти незаявленный input.</p>\n<p><strong>Источник:</strong> <a href=\"https://ccache.dev/manual/latest.html\">ccache manual</a>; <a href=\"https://docs.github.com/en/actions/using-workflows/caching-dependencies-to-speed-up-workflows\">GitHub: Caching dependencies</a></p>\n","group":"L3","line":411},{"id":"content/06_tools_build_debug/06_ci.md:aee4b5e459599d5c:1","question":"<p>(L3, S) Как определить политику invalidation для build cache?</p>\n","answer":"<p><strong>Ответ:</strong> Версионировать cache schema, учитывать влияющие inputs и регулярно проверять clean build equivalence.</p>\n<p><strong>Источник:</strong> <a href=\"https://ccache.dev/manual/latest.html\">ccache manual</a>; <a href=\"https://docs.github.com/en/actions/using-workflows/caching-dependencies-to-speed-up-workflows\">GitHub: Caching dependencies</a></p>\n","group":"L3","line":417},{"id":"content/06_tools_build_debug/06_ci.md:097107f7909d8150:1","question":"<p>(L3, S) Когда cache становится архитектурной зависимостью и риском?</p>\n","answer":"<p><strong>Ответ:</strong> Когда без него pipeline не укладывается в SLA или перестаёт работать; нужны fallback capacity и failure policy.</p>\n<p><strong>Источник:</strong> <a href=\"https://ccache.dev/manual/latest.html\">ccache manual</a>; <a href=\"https://docs.github.com/en/actions/using-workflows/caching-dependencies-to-speed-up-workflows\">GitHub: Caching dependencies</a></p>\n","group":"L3","line":423},{"id":"content/06_tools_build_debug/06_ci.md:51d7c94b417eb0da:1","question":"<p>(L4, S) Как строить стратегию кэширования для большого C++ CI/CD?</p>\n","answer":"<p><strong>Ответ:</strong> Разделить dependency, compile и artifact layers; назначить trust boundaries, retention, metrics и clean validation.</p>\n<p><strong>Источник:</strong> <a href=\"https://ccache.dev/manual/latest.html\">ccache manual</a>; <a href=\"https://docs.github.com/en/actions/using-workflows/caching-dependencies-to-speed-up-workflows\">GitHub: Caching dependencies</a></p>\n","group":"L4","line":432},{"id":"content/06_tools_build_debug/06_ci.md:a4d0a89da860397b:1","question":"<p>(L4, S) Как балансировать скорость pipeline и надежность invalidation?</p>\n","answer":"<p><strong>Ответ:</strong> Предпочитать conservative misses неверным hits, но измерять цену; корректный dependency graph важнее хитрых restore prefixes.</p>\n<p><strong>Источник:</strong> <a href=\"https://ccache.dev/manual/latest.html\">ccache manual</a>; <a href=\"https://docs.github.com/en/actions/using-workflows/caching-dependencies-to-speed-up-workflows\">GitHub: Caching dependencies</a></p>\n","group":"L4","line":438},{"id":"content/06_tools_build_debug/06_ci.md:5883e6d2ace944ca:1","question":"<p>(L4, D) Как расследовать production issue, если подозрение падает на CI artifacts/cache pollution?</p>\n","answer":"<p><strong>Ответ:</strong> Сохранить исходный artifact и manifest, проверить provenance, cache writers и clean rebuild; не перезаписывать evidence.</p>\n<p><strong>Источник:</strong> <a href=\"https://ccache.dev/manual/latest.html\">ccache manual</a>; <a href=\"https://docs.github.com/en/actions/using-workflows/caching-dependencies-to-speed-up-workflows\">GitHub: Caching dependencies</a></p>\n","group":"L4","line":444},{"id":"content/06_tools_build_debug/06_ci.md:7f1575eb6e325858:1","question":"<p>(L4, S) Как измерять ROI от build caching на уровне организации?</p>\n","answer":"<p><strong>Ответ:</strong> Сравнить сэкономленные compute/wait hours с storage/network и maintenance costs; учитывать влияние на developer feedback.</p>\n<p><strong>Источник:</strong> <a href=\"https://ccache.dev/manual/latest.html\">ccache manual</a>; <a href=\"https://docs.github.com/en/actions/using-workflows/caching-dependencies-to-speed-up-workflows\">GitHub: Caching dependencies</a></p>\n","group":"L4","line":450},{"id":"content/06_tools_build_debug/06_ci.md:acba65e89b09d420:1","question":"<p>(L4, S) Как проектировать artifact flow между build, test, package, deploy стадиями?</p>\n","answer":"<p><strong>Ответ:</strong> Build создаёт immutable manifest-addressed artifact, test валидирует его, package/deploy сохраняют связь hashes и provenance.</p>\n<p><strong>Источник:</strong> <a href=\"https://ccache.dev/manual/latest.html\">ccache manual</a>; <a href=\"https://docs.github.com/en/actions/using-workflows/caching-dependencies-to-speed-up-workflows\">GitHub: Caching dependencies</a></p>\n<hr />\n","group":"L4","line":456},{"id":"content/06_tools_build_debug/06_ci.md:af215b16e5d19308:1","question":"<p>(L1, T) Что такое GitHub Actions?</p>\n","answer":"<p><strong>Ответ:</strong> Платформа GitHub для запуска автоматических workflows по repository events и другим triggers.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.github.com/en/actions\">GitHub Actions documentation</a></p>\n","group":"L1","line":471},{"id":"content/06_tools_build_debug/06_ci.md:01cb75180c287be6:1","question":"<p>(L1, T) Что такое workflow?</p>\n","answer":"<p><strong>Ответ:</strong> Описанная YAML автоматизация с triggers, jobs и permissions, обычно в <code>.github/workflows/</code>.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.github.com/en/actions\">GitHub Actions documentation</a></p>\n","group":"L1","line":477},{"id":"content/06_tools_build_debug/06_ci.md:10a534b5be90b5c6:1","question":"<p>(L1, T) Что такое job?</p>\n","answer":"<p><strong>Ответ:</strong> Набор steps на runner; jobs могут выполняться параллельно или зависеть через needs.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.github.com/en/actions\">GitHub Actions documentation</a></p>\n","group":"L1","line":483},{"id":"content/06_tools_build_debug/06_ci.md:5d42ea890421fa3b:1","question":"<p>(L1, T) Что такое step?</p>\n","answer":"<p><strong>Ответ:</strong> Отдельная команда <code>run</code> или вызываемый action <code>uses</code> внутри job.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.github.com/en/actions\">GitHub Actions documentation</a></p>\n","group":"L1","line":489},{"id":"content/06_tools_build_debug/06_ci.md:bdccc6a6382634a6:1","question":"<p>(L1, P) Как на базовом уровне запустить CMake build в GitHub Actions?</p>\n","answer":"<p><strong>Ответ:</strong> После checkout/setup выполнить CMake configure/build и CTest в steps; выбрать доступный runner/toolchain и сохранить logs.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.github.com/en/actions\">GitHub Actions documentation</a></p>\n","group":"L1","line":495},{"id":"content/06_tools_build_debug/06_ci.md:d8ef32f0de7640d5:1","question":"<p>(L2, T) Что такое runners?</p>\n","answer":"<p><strong>Ответ:</strong> Машины или execution environments, на которых исполняются jobs.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.github.com/en/actions\">GitHub Actions documentation</a></p>\n","group":"L2","line":504},{"id":"content/06_tools_build_debug/06_ci.md:e8373875d40d03fb:1","question":"<p>(L2, T) Разница между hosted runner и self-hosted runner?</p>\n","answer":"<p><strong>Ответ:</strong> Hosted обслуживает провайдер; self-hosted обслуживает команда, включая обновления, isolation и cleanup.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.github.com/en/actions\">GitHub Actions documentation</a></p>\n","group":"L2","line":510},{"id":"content/06_tools_build_debug/06_ci.md:2b1fec6b0fa0b1d7:1","question":"<p>(L2, P) Как настроить matrix build для GCC и Clang?</p>\n","answer":"<p><strong>Ответ:</strong> Добавить <code>strategy.matrix</code> с compiler entries и выбрать согласованные CC/CXX при configure в отдельный build directory.</p>\n<p><strong>Пример:</strong> Фрагмент job GitHub Actions для Linux runner с установленными GCC/Clang; checkout и setup выполняются предыдущими steps.</p>\n<pre><code class=\"language-yaml\">strategy:\n  fail-fast: false\n  matrix:\n    include:\n      - { cc: gcc, cxx: g++ }\n      - { cc: clang, cxx: clang++ }\nsteps:\n  - name: Configure\n    env:\n      CC: ${{ matrix.cc }}\n      CXX: ${{ matrix.cxx }}\n    run: cmake -S . -B build -DCMAKE_BUILD_TYPE=RelWithDebInfo\n  - name: Build\n    run: cmake --build build --parallel 2\n  - name: Test\n    run: ctest --test-dir build --output-on-failure\n</code></pre>\n<p>Каждая matrix entry — отдельный job; versions compilers задаёт setup/image, а имена gcc/clang сами их не фиксируют.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.github.com/en/actions\">GitHub Actions documentation</a></p>\n","group":"L2","line":516},{"id":"content/06_tools_build_debug/06_ci.md:16ab60a06fc92c54:1","question":"<p>(L2, P) Как кэшировать зависимости в GitHub Actions?</p>\n","answer":"<p><strong>Ответ:</strong> Подключить cache action с platform/lockfile key и правильным path; cache actions фиксировать на reviewed commit.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.github.com/en/actions\">GitHub Actions documentation</a></p>\n","group":"L2","line":545},{"id":"content/06_tools_build_debug/06_ci.md:58875f7b0675d9f2:1","question":"<p>(L2, D) Почему workflow может вести себя по-разному на разных runner'ах?</p>\n","answer":"<p><strong>Ответ:</strong> Различаются images, packages, CPU, permissions, network и workspace state; сохранять environment manifest.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.github.com/en/actions\">GitHub Actions documentation</a></p>\n","group":"L2","line":551},{"id":"content/06_tools_build_debug/06_ci.md:e4de3e9789a0507c:1","question":"<p>(L2, T) Как работают artifacts в GitHub Actions?</p>\n","answer":"<p><strong>Ответ:</strong> Uploaded files принадлежат конкретному workflow run и могут передаваться между jobs или скачиваться для анализа.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.github.com/en/actions\">GitHub Actions documentation</a></p>\n","group":"L2","line":557},{"id":"content/06_tools_build_debug/06_ci.md:99d64de4467f09ae:1","question":"<p>(L2, P) Как публиковать build artifacts?</p>\n","answer":"<p><strong>Ответ:</strong> Использовать upload-artifact action, задав paths, name и retention; публиковать exact binaries, symbols и reports.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.github.com/en/actions\">GitHub Actions documentation</a></p>\n","group":"L2","line":563},{"id":"content/06_tools_build_debug/06_ci.md:b9e4699bd3cc2b5b:1","question":"<p>(L2, D) Почему job не видит файлы из предыдущего job без artifact/cache?</p>\n","answer":"<p><strong>Ответ:</strong> Hosted jobs обычно выполняются в отдельных environments; локальная файловая система не является межjob контрактом.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.github.com/en/actions\">GitHub Actions documentation</a></p>\n","group":"L2","line":569},{"id":"content/06_tools_build_debug/06_ci.md:7ee720a47094a79e:1","question":"<p>(L2, T) Как ограничивать запуск workflow по branch/tag/path?</p>\n","answer":"<p><strong>Ответ:</strong> Использовать documented event filters branches/tags/paths и conditions; required checks не должны навсегда ждать skipped workflow.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.github.com/en/actions\">GitHub Actions documentation</a></p>\n","group":"L2","line":575},{"id":"content/06_tools_build_debug/06_ci.md:f6e2111d4fa26c4e:1","question":"<p>(L2, P) Как вынести повторяющуюся логику в reusable workflow/action?</p>\n","answer":"<p><strong>Ответ:</strong> Reusable workflow вызывается через workflow_call; composite action объединяет steps. Inputs и permissions задавать явно.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.github.com/en/actions\">GitHub Actions documentation</a></p>\n","group":"L2","line":581},{"id":"content/06_tools_build_debug/06_ci.md:fe1b4c41e179be3f:1","question":"<p>(L3, S) Как проектировать GitHub Actions workflow для большого C++ проекта?</p>\n","answer":"<p><strong>Ответ:</strong> Reusable setup, dependency DAG, supported matrix, cache trust policy и отдельный artifact flow test/package/release.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.github.com/en/actions\">GitHub Actions documentation</a></p>\n","group":"L3","line":590},{"id":"content/06_tools_build_debug/06_ci.md:e6bf00cd7be5b66c:1","question":"<p>(L3, D) Как расследовать нестабильные падения на hosted runners?</p>\n","answer":"<p><strong>Ответ:</strong> Сохранить runner image/version, logs, resource usage и seed; повторить на том же image и проверить test isolation.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.github.com/en/actions\">GitHub Actions documentation</a></p>\n","group":"L3","line":596},{"id":"content/06_tools_build_debug/06_ci.md:1f978e4c0b603d74:1","question":"<p>(L3, P) Как организовать fast checks vs full checks в GitHub Actions?</p>\n","answer":"<p><strong>Ответ:</strong> PR выполняет быстрый gate, schedule — расширенную matrix, release — validation exact artifact; dependencies описать через needs.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.github.com/en/actions\">GitHub Actions documentation</a></p>\n","group":"L3","line":602},{"id":"content/06_tools_build_debug/06_ci.md:c089606acc2613f4:1","question":"<p>(L3, D) Почему self-hosted runner может быть и преимуществом, и источником проблем?</p>\n","answer":"<p><strong>Ответ:</strong> Даёт нужное железо и cache locality, но приносит persistent state, maintenance и риск исполнения untrusted code.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.github.com/en/actions\">GitHub Actions documentation</a></p>\n","group":"L3","line":608},{"id":"content/06_tools_build_debug/06_ci.md:fd475ca9bd1cb46c:1","question":"<p>(L3, T) Как secrets и permissions влияют на безопасность pipeline?</p>\n","answer":"<p><strong>Ответ:</strong> Permissions задают возможности token, secrets дают внешние полномочия; использовать минимальный scope и не раскрывать их untrusted jobs.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.github.com/en/actions\">GitHub Actions documentation</a></p>\n","group":"L3","line":614},{"id":"content/06_tools_build_debug/06_ci.md:1d5b2063091f92c8:1","question":"<p>(L3, D) Как диагностировать проблемы с cache/artifact reuse в GitHub Actions?</p>\n","answer":"<p><strong>Ответ:</strong> Сверить keys, hit/miss, artifact name/run IDs и hashes; случайный restore prefix может выбрать чужую конфигурацию.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.github.com/en/actions\">GitHub Actions documentation</a></p>\n","group":"L3","line":620},{"id":"content/06_tools_build_debug/06_ci.md:0c9460f586e9a409:1","question":"<p>(L3, P) Как интегрировать clang-tidy и тестовые отчеты в PR workflow?</p>\n","answer":"<p><strong>Ответ:</strong> Запускать versioned clang-tidy, сохранять logs и CTest/JUnit reports; комментарии/annotations публиковать только с нужными permissions.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.github.com/en/actions\">GitHub Actions documentation</a></p>\n","group":"L3","line":626},{"id":"content/06_tools_build_debug/06_ci.md:3531813a699106f9:1","question":"<p>(L3, S) Когда нужна split-архитектура: PR CI, nightly CI, release workflow?</p>\n","answer":"<p><strong>Ответ:</strong> Когда PR требует быстрого feedback, nightly — глубины, а release — отдельного доверенного контекста и traceable artifacts.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.github.com/en/actions\">GitHub Actions documentation</a></p>\n","group":"L3","line":632},{"id":"content/06_tools_build_debug/06_ci.md:2e17d1e7dcd1daf4:1","question":"<p>(L3, D) Как уменьшить стоимость GitHub Actions для тяжелых C++ сборок?</p>\n","answer":"<p><strong>Ответ:</strong> Убрать дублирующие runs, parallelize critical path, use compiler cache и affected tests; измерять стоимость и надёжность.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.github.com/en/actions\">GitHub Actions documentation</a></p>\n","group":"L3","line":638},{"id":"content/06_tools_build_debug/06_ci.md:765271d11f1f44f4:1","question":"<p>(L3, S) Как формализовать правила merge protection через GitHub Actions?</p>\n","answer":"<p><strong>Ответ:</strong> Настроить required status checks с устойчивыми именами и branch protection/rulesets; не превращать skipped checks в обход gates.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.github.com/en/actions\">GitHub Actions documentation</a></p>\n","group":"L3","line":644},{"id":"content/06_tools_build_debug/06_ci.md:4919c43c3850286f:1","question":"<p>(L4, S) Как строить GitHub Actions platform strategy для нескольких C++ репозиториев?</p>\n","answer":"<p><strong>Ответ:</strong> Versioned reusable workflows, pinned dependencies/actions, runner classes и ownership с rollout/canary policy.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.github.com/en/actions\">GitHub Actions documentation</a></p>\n","group":"L4","line":653},{"id":"content/06_tools_build_debug/06_ci.md:510afde7e8334adc:1","question":"<p>(L4, S) Когда self-hosted runners оправданы организационно и технически?</p>\n","answer":"<p><strong>Ответ:</strong> Для special hardware, capacity/latency или isolation requirements, когда команда готова обслуживать infrastructure и trust boundaries.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.github.com/en/actions\">GitHub Actions documentation</a></p>\n","group":"L4","line":659},{"id":"content/06_tools_build_debug/06_ci.md:9bfc7205c9ed6026:1","question":"<p>(L4, D) Как расследовать supply-chain/security incident, связанный с GitHub Actions?</p>\n","answer":"<p><strong>Ответ:</strong> Сохранить logs, workflow revision, action SHAs, token scopes и artifact provenance; отозвать скомпрометированные credentials и определить blast radius.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.github.com/en/actions\">GitHub Actions documentation</a></p>\n","group":"L4","line":665},{"id":"content/06_tools_build_debug/06_ci.md:6db7fecec4593162:1","question":"<p>(L4, S) Как стандартизировать reusable workflows для команды/организации?</p>\n","answer":"<p><strong>Ответ:</strong> Явные inputs/outputs, versioned contracts, tests templates и поэтапное обновление consumers.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.github.com/en/actions\">GitHub Actions documentation</a></p>\n","group":"L4","line":671},{"id":"content/06_tools_build_debug/06_ci.md:ad1418b602501d28:1","question":"<p>(L4, S) Как построить надежную release automation поверх GitHub Actions?</p>\n","answer":"<p><strong>Ответ:</strong> Собирать проверенный immutable artifact, хранить provenance, ограничить release credentials и протестировать rollback/idempotent retries.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.github.com/en/actions\">GitHub Actions documentation</a></p>\n","group":"L4","line":677},{"id":"content/06_tools_build_debug/06_ci.md:7b42facb7514e08b:1","question":"<p>(L1, T) Что такое GitLab CI pipeline?</p>\n","answer":"<p><strong>Ответ:</strong> Набор связанных jobs проекта, конфигурируемый обычно через <code>.gitlab-ci.yml</code> и выполняемый runners.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.gitlab.com/ci/\">GitLab CI/CD documentation</a></p>\n","group":"L1","line":688},{"id":"content/06_tools_build_debug/06_ci.md:deaac54984bcf5bc:1","question":"<p>(L1, T) Что такое stages в GitLab CI?</p>\n","answer":"<p><strong>Ответ:</strong> Логические группы jobs с порядком исполнения; needs может задавать более точный DAG.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.gitlab.com/ci/\">GitLab CI/CD documentation</a></p>\n","group":"L1","line":694},{"id":"content/06_tools_build_debug/06_ci.md:a34f83b1d4977702:1","question":"<p>(L1, T) Что такое runner в GitLab CI?</p>\n","answer":"<p><strong>Ответ:</strong> Agent, забирающий jobs и исполняющий их через настроенный executor.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.gitlab.com/ci/\">GitLab CI/CD documentation</a></p>\n","group":"L1","line":700},{"id":"content/06_tools_build_debug/06_ci.md:c0900965063bbd7d:1","question":"<p>(L1, P) Как описывается pipeline в GitLab CI?</p>\n","answer":"<p><strong>Ответ:</strong> YAML с jobs, scripts, stages/rules и environment configuration; reusable sections подключаются include/templates.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.gitlab.com/ci/\">GitLab CI/CD documentation</a></p>\n","group":"L1","line":706},{"id":"content/06_tools_build_debug/06_ci.md:29e05666cff5094f:1","question":"<p>(L1, P) Как на базовом уровне запустить сборку C++ проекта в GitLab CI?</p>\n","answer":"<p><strong>Ответ:</strong> Выбрать pinned image с toolchain, затем в script выполнить cmake configure/build и ctest с failure output.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.gitlab.com/ci/\">GitLab CI/CD documentation</a></p>\n","group":"L1","line":712},{"id":"content/06_tools_build_debug/06_ci.md:0782057e17bd27f4:1","question":"<p>(L2, T) Что такое jobs, stages, dependencies в GitLab CI?</p>\n","answer":"<p><strong>Ответ:</strong> Jobs выполняют работу, stages группируют порядок; dependencies определяет получение artifacts, needs — execution DAG и при настройке artifacts.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.gitlab.com/ci/\">GitLab CI/CD documentation</a></p>\n","group":"L2","line":721},{"id":"content/06_tools_build_debug/06_ci.md:f8b8a32bb9c91167:1","question":"<p>(L2, T) Что такое artifacts и cache в GitLab CI?</p>\n","answer":"<p><strong>Ответ:</strong> Artifacts — outputs конкретного job для передачи/хранения; cache — best-effort reuse files между runs.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.gitlab.com/ci/\">GitLab CI/CD documentation</a></p>\n","group":"L2","line":727},{"id":"content/06_tools_build_debug/06_ci.md:bcc572b4b5171d41:1","question":"<p>(L2, P) Как передать build artifacts между jobs?</p>\n","answer":"<p><strong>Ответ:</strong> Объявить producer <code>artifacts:paths</code>, consumer связать через needs с artifacts либо documented dependencies.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.gitlab.com/ci/\">GitLab CI/CD documentation</a></p>\n","group":"L2","line":733},{"id":"content/06_tools_build_debug/06_ci.md:17964d850a5ee1f4:1","question":"<p>(L2, P) Как настроить matrix-like проверки через parallel/variables?</p>\n","answer":"<p><strong>Ответ:</strong> Использовать <code>parallel:matrix</code> с compiler/build type variables и отдельными именами outputs.</p>\n<p><strong>Пример:</strong> Фрагмент GitLab CI; runner/image должен содержать указанные компиляторы и CMake.</p>\n<pre><code class=\"language-yaml\">build-and-test:\n  parallel:\n    matrix:\n      - CC: gcc\n        CXX: g++\n      - CC: clang\n        CXX: clang++\n  script:\n    - cmake -S . -B build -DCMAKE_BUILD_TYPE=RelWithDebInfo\n    - cmake --build build --parallel 2\n    - ctest --test-dir build --output-on-failure\n</code></pre>\n<p>Для публикации artifacts задают уникальные имена по compiler/config, чтобы downstream не перезаписал outputs разных jobs.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.gitlab.com/ci/\">GitLab CI/CD documentation</a></p>\n","group":"L2","line":739},{"id":"content/06_tools_build_debug/06_ci.md:238d34270ceeebbe:1","question":"<p>(L2, D) Почему pipeline проходит в одном runner environment и падает в другом?</p>\n","answer":"<p><strong>Ответ:</strong> Различаются executor/image, architecture, permissions, resources и dependency state; compare environment manifests.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.gitlab.com/ci/\">GitLab CI/CD documentation</a></p>\n","group":"L2","line":763},{"id":"content/06_tools_build_debug/06_ci.md:167313128d9375de:1","question":"<p>(L2, T) Как работают rules / only / except?</p>\n","answer":"<p><strong>Ответ:</strong> Rules управляют включением job и параметрами по условиям; legacy only/except менее гибки и не должны бессистемно смешиваться.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.gitlab.com/ci/\">GitLab CI/CD documentation</a></p>\n","group":"L2","line":769},{"id":"content/06_tools_build_debug/06_ci.md:12f1fbd80de25ccc:1","question":"<p>(L2, P) Как запускать разные jobs для merge request и для main branch?</p>\n","answer":"<p><strong>Ответ:</strong> Использовать rules по CI_PIPELINE_SOURCE для merge_request_event и по CI_COMMIT_BRANCH для main; избежать duplicate pipelines.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.gitlab.com/ci/\">GitLab CI/CD documentation</a></p>\n","group":"L2","line":775},{"id":"content/06_tools_build_debug/06_ci.md:bc033a8c9372ccbb:1","question":"<p>(L2, D) Почему кэш в GitLab CI может быть неэффективен?</p>\n","answer":"<p><strong>Ответ:</strong> Key слишком специфичен, path неверен, cache недоступен разным runners либо передача дороже восстановления inputs.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.gitlab.com/ci/\">GitLab CI/CD documentation</a></p>\n","group":"L2","line":781},{"id":"content/06_tools_build_debug/06_ci.md:9287843806dd1e5e:1","question":"<p>(L2, T) В чем разница cache vs artifacts в GitLab CI?</p>\n","answer":"<p><strong>Ответ:</strong> Cache ускоряет повторные jobs без гарантии наличия; artifacts задают передачу exact outputs данного pipeline.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.gitlab.com/ci/\">GitLab CI/CD documentation</a></p>\n","group":"L2","line":787},{"id":"content/06_tools_build_debug/06_ci.md:6da684efb8442b06:1","question":"<p>(L2, P) Как подключить тестовые отчеты и coverage в GitLab CI?</p>\n","answer":"<p><strong>Ответ:</strong> Публиковать supported <code>artifacts:reports:junit</code> и coverage_report с правильным форматом; text coverage extraction — отдельная настройка.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.gitlab.com/ci/\">GitLab CI/CD documentation</a></p>\n","group":"L2","line":793},{"id":"content/06_tools_build_debug/06_ci.md:5852a9de28086ffa:1","question":"<p>(L3, S) Как спроектировать GitLab CI для monorepo или большого C++ проекта?</p>\n","answer":"<p><strong>Ответ:</strong> Affected graph, child pipelines для компонентов, общие templates и периодическая full validation поддерживаемой matrix.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.gitlab.com/ci/\">GitLab CI/CD documentation</a></p>\n","group":"L3","line":802},{"id":"content/06_tools_build_debug/06_ci.md:3c14b8f087c910ff:1","question":"<p>(L3, D) Как расследовать нестабильность self-managed runner'ов?</p>\n","answer":"<p><strong>Ответ:</strong> Проверить executor state, image digest, disk/memory pressure, concurrent jobs и runner version/config.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.gitlab.com/ci/\">GitLab CI/CD documentation</a></p>\n","group":"L3","line":808},{"id":"content/06_tools_build_debug/06_ci.md:b239d1e6a50d50ab:1","question":"<p>(L3, T) Как выбирать между shared runners и dedicated runners?</p>\n","answer":"<p><strong>Ответ:</strong> По требованиям isolation, hardware и predictable capacity; dedicated runners требуют собственной эксплуатации.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.gitlab.com/ci/\">GitLab CI/CD documentation</a></p>\n","group":"L3","line":814},{"id":"content/06_tools_build_debug/06_ci.md:3f18b7470050fe04:1","question":"<p>(L3, P) Как внедрить sanitizer/static analysis/nightly jobs в GitLab CI?</p>\n","answer":"<p><strong>Ответ:</strong> Отдельные jobs/configs с sanitizer flags, analyzer scripts и schedule rules; reports сохранять даже при failed test.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.gitlab.com/ci/\">GitLab CI/CD documentation</a></p>\n","group":"L3","line":820},{"id":"content/06_tools_build_debug/06_ci.md:c87df56c172b3ffe:1","question":"<p>(L3, D) Почему pipeline может быть медленнее из-за плохого stage design?</p>\n","answer":"<p><strong>Ответ:</strong> Грубые stage barriers заставляют независимые jobs ждать; needs сокращает DAG без нарушения artifact dependencies.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.gitlab.com/ci/\">GitLab CI/CD documentation</a></p>\n","group":"L3","line":826},{"id":"content/06_tools_build_debug/06_ci.md:7d9b68d868c043fe:1","question":"<p>(L3, S) Как организовать child pipelines / include templates для переиспользования?</p>\n","answer":"<p><strong>Ответ:</strong> Versioned include templates и trigger child pipelines; явно задавать inputs/variables и propagation failure status.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.gitlab.com/ci/\">GitLab CI/CD documentation</a></p>\n","group":"L3","line":832},{"id":"content/06_tools_build_debug/06_ci.md:14a7828bfad0030f:1","question":"<p>(L3, D) Как разбирать CI failures, вызванные container image drift?</p>\n","answer":"<p><strong>Ответ:</strong> Сравнить resolved image digests, compiler/package versions; воспроизвести на старом image и протестировать новый отдельно.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.gitlab.com/ci/\">GitLab CI/CD documentation</a></p>\n","group":"L3","line":838},{"id":"content/06_tools_build_debug/06_ci.md:93c2bad313a35279:1","question":"<p>(L3, T) Как GitLab environments/review apps соотносятся с C++ сервисами?</p>\n","answer":"<p><strong>Ответ:</strong> Описывают deployment targets и временные test environments; C++ service обычно доставляется как package/container с доступными dependencies.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.gitlab.com/ci/\">GitLab CI/CD documentation</a></p>\n","group":"L3","line":844},{"id":"content/06_tools_build_debug/06_ci.md:5edc4dd905d0be25:1","question":"<p>(L3, S) Как управлять секретами и доступами в GitLab CI?</p>\n","answer":"<p><strong>Ответ:</strong> Scoped/protected variables, минимальные token permissions и разграничение trusted/untrusted runners; secrets не должны попадать в artifacts.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.gitlab.com/ci/\">GitLab CI/CD documentation</a></p>\n","group":"L3","line":850},{"id":"content/06_tools_build_debug/06_ci.md:5682aebeecd6e282:1","question":"<p>(L3, D) Как уменьшить очередь и latency pipeline execution в GitLab CI?</p>\n","answer":"<p><strong>Ответ:</strong> Измерить queue vs execution, добавить подходящую capacity, убрать лишние runs и parallelize независимые jobs.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.gitlab.com/ci/\">GitLab CI/CD documentation</a></p>\n","group":"L3","line":856},{"id":"content/06_tools_build_debug/06_ci.md:ad2984015b8ffe34:1","question":"<p>(L4, S) Как построить GitLab CI platform для нескольких C/C++ команд?</p>\n","answer":"<p><strong>Ответ:</strong> Общие versioned templates, runner pools по workload/trust и service ownership с метриками latency/reliability.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.gitlab.com/ci/\">GitLab CI/CD documentation</a></p>\n","group":"L4","line":865},{"id":"content/06_tools_build_debug/06_ci.md:8e3709bee00a4b25:1","question":"<p>(L4, S) Как формализовать governance вокруг pipeline templates и runners?</p>\n","answer":"<p><strong>Ответ:</strong> Определить owners, review/rollback templates, image update cadence и security boundaries runners.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.gitlab.com/ci/\">GitLab CI/CD documentation</a></p>\n","group":"L4","line":871},{"id":"content/06_tools_build_debug/06_ci.md:c8e130c9a8499b55:1","question":"<p>(L4, D) Как расследовать incidents, вызванные изменением runner image/toolchain?</p>\n","answer":"<p><strong>Ответ:</strong> Привязать failures к image/toolchain change, сохранить old/new manifests, выполнить canary comparison и откатить подтверждённую регрессию.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.gitlab.com/ci/\">GitLab CI/CD documentation</a></p>\n","group":"L4","line":877},{"id":"content/06_tools_build_debug/06_ci.md:fe2cacac77014921:1","question":"<p>(L4, S) Как совместить скорость merge-request pipeline и глубину release validation?</p>\n","answer":"<p><strong>Ответ:</strong> PR — high-signal short checks, schedule — broad matrix, release — validation публикуемого artifact и supported targets.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.gitlab.com/ci/\">GitLab CI/CD documentation</a></p>\n","group":"L4","line":883},{"id":"content/06_tools_build_debug/06_ci.md:f8308818d635699b:1","question":"<p>(L4, S) Как строить release engineering практику вокруг GitLab CI?</p>\n","answer":"<p><strong>Ответ:</strong> Versioned packaging, immutable artifacts, provenance, compatibility tests и документированный release/rollback lifecycle.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.gitlab.com/ci/\">GitLab CI/CD documentation</a></p>\n","group":"L4","line":889},{"id":"content/06_tools_build_debug/06_ci.md:d92890eccaa2f926:1","question":"<p>(L1, T) Что такое Jenkins?</p>\n","answer":"<p><strong>Ответ:</strong> CI automation server с extensible plugins и выполнением jobs на agents.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.jenkins.io/doc/book/pipeline/\">Jenkins Pipeline</a></p>\n","group":"L1","line":900},{"id":"content/06_tools_build_debug/06_ci.md:0b875e26cad8869f:1","question":"<p>(L1, T) В чем базовая идея Jenkins pipeline?</p>\n","answer":"<p><strong>Ответ:</strong> Описывать checkout/build/test/package как versioned pipeline с явными stages, inputs и failure semantics.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.jenkins.io/doc/book/pipeline/\">Jenkins Pipeline</a></p>\n","group":"L1","line":906},{"id":"content/06_tools_build_debug/06_ci.md:bf34411ebc6e0f79:1","question":"<p>(L1, T) Что такое Jenkins agent?</p>\n","answer":"<p><strong>Ответ:</strong> Execution node для jobs; controller управляет orchestration, а heavy build лучше выполнять на agents.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.jenkins.io/doc/book/pipeline/\">Jenkins Pipeline</a></p>\n","group":"L1","line":912},{"id":"content/06_tools_build_debug/06_ci.md:598103b89ce6d4ff:1","question":"<p>(L1, T) Что такое Jenkinsfile?</p>\n","answer":"<p><strong>Ответ:</strong> Файл pipeline-as-code в репозитории, обычно Declarative или Scripted Pipeline.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.jenkins.io/doc/book/pipeline/\">Jenkins Pipeline</a></p>\n","group":"L1","line":918},{"id":"content/06_tools_build_debug/06_ci.md:8c4fffd056d4e164:1","question":"<p>(L1, P) Как на базовом уровне описать C++ build job в Jenkins?</p>\n","answer":"<p><strong>Ответ:</strong> В Jenkinsfile определить agent и stages с <code>sh</code> для cmake configure/build и ctest; сохранять test reports в post.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.jenkins.io/doc/book/pipeline/\">Jenkins Pipeline</a></p>\n","group":"L1","line":924},{"id":"content/06_tools_build_debug/06_ci.md:6a4e2cbcfa74d291:1","question":"<p>(L2, T) Разница freestyle jobs vs pipeline as code?</p>\n","answer":"<p><strong>Ответ:</strong> Freestyle настраивается преимущественно через UI; pipeline-as-code версионирует логику и позволяет review вместе с исходниками.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.jenkins.io/doc/book/pipeline/\">Jenkins Pipeline</a></p>\n","group":"L2","line":933},{"id":"content/06_tools_build_debug/06_ci.md:dccda0f63e0211e6:1","question":"<p>(L2, P) Как разбить Jenkins pipeline на stages?</p>\n","answer":"<p><strong>Ответ:</strong> Declarative <code>stages { stage('Build') { steps { ... } } }</code>; boundaries выбирать по зависимости и диагностике.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.jenkins.io/doc/book/pipeline/\">Jenkins Pipeline</a></p>\n","group":"L2","line":939},{"id":"content/06_tools_build_debug/06_ci.md:78f9a81f389148a5:1","question":"<p>(L2, P) Как сохранять artifacts в Jenkins?</p>\n","answer":"<p><strong>Ответ:</strong> Использовать archiveArtifacts для outputs; stash/unstash предназначены для передачи в рамках pipeline и не заменяют release repository.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.jenkins.io/doc/book/pipeline/\">Jenkins Pipeline</a></p>\n","group":"L2","line":945},{"id":"content/06_tools_build_debug/06_ci.md:9ee9e12976f735af:1","question":"<p>(L2, D) Почему Jenkins job может зависеть от состояния машины-агента?</p>\n","answer":"<p><strong>Ответ:</strong> Workspace, installed packages, environment и external files могут сохраняться между runs и образовывать скрытые dependencies.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.jenkins.io/doc/book/pipeline/\">Jenkins Pipeline</a></p>\n","group":"L2","line":951},{"id":"content/06_tools_build_debug/06_ci.md:85f4570315702a8f:1","question":"<p>(L2, T) Почему Jenkins historically часто ассоциируется с “snowflake CI”?</p>\n","answer":"<p><strong>Ответ:</strong> Ручные UI configs и индивидуально настроенные agents исторически создавали уникальные environments; Jenkins не требует такого подхода.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.jenkins.io/doc/book/pipeline/\">Jenkins Pipeline</a></p>\n","group":"L2","line":957},{"id":"content/06_tools_build_debug/06_ci.md:a0c5d707aa8bb353:1","question":"<p>(L2, P) Как параметризовать pipeline по compiler/build type?</p>\n","answer":"<p><strong>Ответ:</strong> Declarative parameters/environment либо matrix axes; compiler и config фиксировать в manifest и отдельном build tree.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.jenkins.io/doc/book/pipeline/\">Jenkins Pipeline</a></p>\n","group":"L2","line":963},{"id":"content/06_tools_build_debug/06_ci.md:e8ef5ef2eced34fa:1","question":"<p>(L2, D) Почему один и тот же job нестабилен на разных agents?</p>\n","answer":"<p><strong>Ответ:</strong> Разные images/toolchains, resources, workspaces и permissions; label сам по себе не доказывает environment equivalence.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.jenkins.io/doc/book/pipeline/\">Jenkins Pipeline</a></p>\n","group":"L2","line":969},{"id":"content/06_tools_build_debug/06_ci.md:8548bc4cad0ef418:1","question":"<p>(L2, T) Как plugins влияют на надежность Jenkins?</p>\n","answer":"<p><strong>Ответ:</strong> Добавляют capabilities, но также dependencies, compatibility и update/security burden.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.jenkins.io/doc/book/pipeline/\">Jenkins Pipeline</a></p>\n","group":"L2","line":975},{"id":"content/06_tools_build_debug/06_ci.md:d08ed979eeac685a:1","question":"<p>(L2, D) Почему Jenkins instance со временем “обрастает” скрытой сложностью?</p>\n","answer":"<p><strong>Ответ:</strong> Накапливаются plugins, scripts, shared state, UI settings и credentials без единого ownership/versioning.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.jenkins.io/doc/book/pipeline/\">Jenkins Pipeline</a></p>\n","group":"L2","line":981},{"id":"content/06_tools_build_debug/06_ci.md:cec1402fc5d21716:1","question":"<p>(L2, P) Как запускать тесты и собирать отчеты в Jenkins?</p>\n","answer":"<p><strong>Ответ:</strong> Запустить CTest с JUnit output при поддержке версии и опубликовать <code>junit</code> report в post/always.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.jenkins.io/doc/book/pipeline/\">Jenkins Pipeline</a></p>\n","group":"L2","line":987},{"id":"content/06_tools_build_debug/06_ci.md:694c04c1f3d595bf:1","question":"<p>(L3, S) Как проектировать Jenkins pipeline для legacy C++ проекта?</p>\n","answer":"<p><strong>Ответ:</strong> Сначала воспроизводимая CLI сборка и artifact identity, затем перенос existing gates в Jenkinsfile без смены смысла тестов.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.jenkins.io/doc/book/pipeline/\">Jenkins Pipeline</a></p>\n","group":"L3","line":996},{"id":"content/06_tools_build_debug/06_ci.md:854e7ef112f03151:1","question":"<p>(L3, D) Как расследовать проблемы из-за дрейфа окружения на agents?</p>\n","answer":"<p><strong>Ответ:</strong> Снять agent/image/package manifest и compare successful/failed run; использовать disposable agents и pinned toolchain.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.jenkins.io/doc/book/pipeline/\">Jenkins Pipeline</a></p>\n","group":"L3","line":1002},{"id":"content/06_tools_build_debug/06_ci.md:62fbceb26ebd63bd:1","question":"<p>(L3, T) Когда Jenkins still makes sense по сравнению с GitHub/GitLab CI?</p>\n","answer":"<p><strong>Ответ:</strong> Когда нужны существующие integrations, special hardware и controlled on-prem operation при приемлемой стоимости сопровождения.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.jenkins.io/doc/book/pipeline/\">Jenkins Pipeline</a></p>\n","group":"L3","line":1008},{"id":"content/06_tools_build_debug/06_ci.md:e52eef10c068471b:1","question":"<p>(L3, P) Как изолировать сборки через containerized agents?</p>\n","answer":"<p><strong>Ответ:</strong> Использовать supported container agents с pinned image; workspace, mounts и privileges тоже входят в isolation contract.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.jenkins.io/doc/book/pipeline/\">Jenkins Pipeline</a></p>\n","group":"L3","line":1014},{"id":"content/06_tools_build_debug/06_ci.md:57f96e10364319d4:1","question":"<p>(L3, D) Почему Jenkins plugins — частый источник operational риска?</p>\n","answer":"<p><strong>Ответ:</strong> Обновления затрагивают dependency graph и совместимость server; plugin выполняет код с существенным доступом.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.jenkins.io/doc/book/pipeline/\">Jenkins Pipeline</a></p>\n","group":"L3","line":1020},{"id":"content/06_tools_build_debug/06_ci.md:08a1eb4d4c218acb:1","question":"<p>(L3, S) Как организовать shared libraries и reusable stages в Jenkins?</p>\n","answer":"<p><strong>Ответ:</strong> Shared Libraries с versioned API и tests; consumer должен контролировать version, а rollout иметь rollback.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.jenkins.io/doc/book/pipeline/\">Jenkins Pipeline</a></p>\n","group":"L3","line":1026},{"id":"content/06_tools_build_debug/06_ci.md:55ef931e8f387a20:1","question":"<p>(L3, D) Как уменьшить build queue и contention на limited agents?</p>\n","answer":"<p><strong>Ответ:</strong> Измерять resource/queue utilization, разграничивать heavy jobs, масштабировать agent pools и избегать конкурирующих builds за один workspace.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.jenkins.io/doc/book/pipeline/\">Jenkins Pipeline</a></p>\n","group":"L3","line":1032},{"id":"content/06_tools_build_debug/06_ci.md:a58a3e3ec37cffc2:1","question":"<p>(L3, S) Как мигрировать Jenkins pipelines без потери контроля над quality gates?</p>\n","answer":"<p><strong>Ответ:</strong> Перенести gates с contract tests и shadow runs; сравнить results/artifacts до включения новой платформы как required.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.jenkins.io/doc/book/pipeline/\">Jenkins Pipeline</a></p>\n","group":"L3","line":1038},{"id":"content/06_tools_build_debug/06_ci.md:e650eb49c5f82144:1","question":"<p>(L3, D) Как диагностировать деградацию производительности Jenkins master/agents?</p>\n","answer":"<p><strong>Ответ:</strong> Проверить controller CPU/heap/GC, plugin load, I/O и agent network/resources; не смешивать controller bottleneck с compile time.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.jenkins.io/doc/book/pipeline/\">Jenkins Pipeline</a></p>\n","group":"L3","line":1044},{"id":"content/06_tools_build_debug/06_ci.md:28769eda2c896653:1","question":"<p>(L3, S) Как управлять секретами и доступом в Jenkins для C++ delivery pipeline?</p>\n","answer":"<p><strong>Ответ:</strong> Credentials bindings и least privilege с scoped access; untrusted builds не должны получать release credentials или privileged agents.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.jenkins.io/doc/book/pipeline/\">Jenkins Pipeline</a></p>\n","group":"L3","line":1050},{"id":"content/06_tools_build_debug/06_ci.md:6e6d270749afa9a4:1","question":"<p>(L4, S) Как принимать решение: оставаться на Jenkins или мигрировать?</p>\n","answer":"<p><strong>Ответ:</strong> Сравнить migration cost, integrations, reliability, security и ownership; наличие legacy pipelines само по себе не решает выбор.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.jenkins.io/doc/book/pipeline/\">Jenkins Pipeline</a></p>\n","group":"L4","line":1059},{"id":"content/06_tools_build_debug/06_ci.md:8bd9baebe74af2f2:1","question":"<p>(L4, S) Как строить governance для Jenkins platform в крупной организации?</p>\n","answer":"<p><strong>Ответ:</strong> Configuration-as-code, approved plugins, managed agent images, owners и staged upgrade policy.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.jenkins.io/doc/book/pipeline/\">Jenkins Pipeline</a></p>\n","group":"L4","line":1065},{"id":"content/06_tools_build_debug/06_ci.md:8b21582ff268ca46:1","question":"<p>(L4, D) Как расследовать supply-chain риски и плагин-зависимости Jenkins?</p>\n","answer":"<p><strong>Ответ:</strong> Инвентаризировать plugins/versions, источники updates и privileges; сопоставить advisories и pipeline credentials exposure.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.jenkins.io/doc/book/pipeline/\">Jenkins Pipeline</a></p>\n","group":"L4","line":1071},{"id":"content/06_tools_build_debug/06_ci.md:30f69e56994f0566:1","question":"<p>(L4, S) Как стандартизировать pipeline-as-code в исторически “ручной” Jenkins среде?</p>\n","answer":"<p><strong>Ответ:</strong> Инвентаризация jobs, reproducible CLI, Jenkinsfile/shared libraries и удаление недокументированных UI dependencies поэтапно.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.jenkins.io/doc/book/pipeline/\">Jenkins Pipeline</a></p>\n","group":"L4","line":1077},{"id":"content/06_tools_build_debug/06_ci.md:5f98ac9db4de0c6b:1","question":"<p>(L4, S) Как организовать поэтапную миграцию legacy Jenkins estate в современную CI/CD платформу?</p>\n","answer":"<p><strong>Ответ:</strong> Классифицировать jobs, перенести типовые, сравнить shadow results, переключать по группам с rollback и retirement plan.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.jenkins.io/doc/book/pipeline/\">Jenkins Pipeline</a></p>\n<hr />\n","group":"L4","line":1083},{"id":"content/06_tools_build_debug/06_ci.md:9bd2d028e93a58dd:1","question":"<p>(L1, T) Что такое clang-tidy?</p>\n","answer":"<p><strong>Ответ:</strong> Clang-based инструмент статического анализа и lint checks для C/C++ с доступом к AST.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/extra/clang-tidy/\">Clang-Tidy</a></p>\n","group":"L1","line":1098},{"id":"content/06_tools_build_debug/06_ci.md:f2a50620d3b89d03:1","question":"<p>(L1, T) Зачем нужен clang-tidy, если код уже компилируется?</p>\n","answer":"<p><strong>Ответ:</strong> Compilation не проверяет все подозрительные паттерны и API misuse; tidy добавляет configurable проверки и некоторые fixes.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/extra/clang-tidy/\">Clang-Tidy</a></p>\n","group":"L1","line":1104},{"id":"content/06_tools_build_debug/06_ci.md:cd5f5980422e76f5:1","question":"<p>(L1, T) Какие типы проблем ищет clang-tidy?</p>\n","answer":"<p><strong>Ответ:</strong> Bug-prone patterns, portability, performance, modernization, readability и analyzer diagnostics; checks зависят от версии.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/extra/clang-tidy/\">Clang-Tidy</a></p>\n","group":"L1","line":1110},{"id":"content/06_tools_build_debug/06_ci.md:af3209e1e647fa06:1","question":"<p>(L1, P) Как запустить clang-tidy локально?</p>\n","answer":"<p><strong>Ответ:</strong> <code>clang-tidy src/main.cpp -p build</code>; build должен содержать актуальную compilation database и generated headers.</p>\n<p><strong>Пример:</strong> Для CMake с Makefiles/Ninja:</p>\n<pre><code class=\"language-bash\">cmake -S . -B build-analysis -DCMAKE_EXPORT_COMPILE_COMMANDS=ON\ncmake --build build-analysis --parallel 2\nclang-tidy src/main.cpp -p build-analysis\n</code></pre>\n<p>Build нужен, если анализируемый TU включает generated headers. Выбранный файл должен присутствовать в database.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/extra/clang-tidy/\">Clang-Tidy</a></p>\n","group":"L1","line":1116},{"id":"content/06_tools_build_debug/06_ci.md:7962c1e001c8d84b:1","question":"<p>(L1, T) Почему clang-tidy опирается на compile_commands.json?</p>\n","answer":"<p><strong>Ответ:</strong> Точные flags, includes и macros нужны для правильного разбора translation unit в контексте проекта.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/extra/clang-tidy/\">Clang-Tidy</a></p>\n","group":"L1","line":1132},{"id":"content/06_tools_build_debug/06_ci.md:5000c13bca86c86e:1","question":"<p>(L2, T) Чем clang-tidy отличается от compiler warnings?</p>\n","answer":"<p><strong>Ответ:</strong> Warnings встроены в compiler pipeline; tidy предоставляет отдельные extensible checks и transformation tooling. Области пересекаются.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/extra/clang-tidy/\">Clang-Tidy</a></p>\n","group":"L2","line":1141},{"id":"content/06_tools_build_debug/06_ci.md:aaf96db77a8794e6:1","question":"<p>(L2, P) Как запускать clang-tidy только на измененных файлах?</p>\n","answer":"<p><strong>Ответ:</strong> Запустить на changed translation units; header changes требуют затронутых consumers. Diff-only reporting не заменяет dependency analysis.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/extra/clang-tidy/\">Clang-Tidy</a></p>\n","group":"L2","line":1147},{"id":"content/06_tools_build_debug/06_ci.md:1899a8cac9693b7d:1","question":"<p>(L2, D) Почему clang-tidy в CI может ругаться на код, который локально “чистый”?</p>\n","answer":"<p><strong>Ответ:</strong> Иные version/checks, compilation database, include paths и macros; сравнивать exact command lines.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/extra/clang-tidy/\">Clang-Tidy</a></p>\n","group":"L2","line":1153},{"id":"content/06_tools_build_debug/06_ci.md:3e594b3fe1876fe9:1","question":"<p>(L2, T) Какие категории проверок бывают у clang-tidy?</p>\n","answer":"<p><strong>Ответ:</strong> Например bugprone, performance, modernize, readability, portability и clang-analyzer; конкретные checks выбирать явно.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/extra/clang-tidy/\">Clang-Tidy</a></p>\n","group":"L2","line":1159},{"id":"content/06_tools_build_debug/06_ci.md:2965f2b3e4dcd217:1","question":"<p>(L2, P) Как настраивать checks через <code>.clang-tidy</code>?</p>\n","answer":"<p><strong>Ответ:</strong> Задать <code>Checks</code>, <code>WarningsAsErrors</code> и CheckOptions; проверить effective configuration через <code>--dump-config</code>.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/extra/clang-tidy/\">Clang-Tidy</a></p>\n","group":"L2","line":1165},{"id":"content/06_tools_build_debug/06_ci.md:f6ebaa10d1a4f82a:1","question":"<p>(L2, D) Почему слишком много правил делает tool бесполезным для команды?</p>\n","answer":"<p><strong>Ответ:</strong> Шум и низкая полезность снижают доверие; правила должны соответствовать реальным рискам и стилю проекта.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/extra/clang-tidy/\">Clang-Tidy</a></p>\n","group":"L2","line":1171},{"id":"content/06_tools_build_debug/06_ci.md:0670fc1ad82c96b6:1","question":"<p>(L2, T) Что такое auto-fix в clang-tidy и где он уместен?</p>\n","answer":"<p><strong>Ответ:</strong> Автоматическое применение предложенных edits; подходит механическим изменениям после review, diff и проверки сборки/тестов.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/extra/clang-tidy/\">Clang-Tidy</a></p>\n","group":"L2","line":1177},{"id":"content/06_tools_build_debug/06_ci.md:ffe5fdb82107643b:1","question":"<p>(L2, D) Как бороться с false positives?</p>\n","answer":"<p><strong>Ответ:</strong> Сначала проверить configuration и reproducer; затем точечный NOLINT с причиной или исправление upstream, без blanket disable.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/extra/clang-tidy/\">Clang-Tidy</a></p>\n","group":"L2","line":1183},{"id":"content/06_tools_build_debug/06_ci.md:98042ec308092641:1","question":"<p>(L2, P) Как встроить clang-tidy в pipeline без чрезмерного времени выполнения?</p>\n","answer":"<p><strong>Ответ:</strong> Анализировать relevant TUs параллельно с bounded memory, reuse build metadata и полный scheduled pass.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/extra/clang-tidy/\">Clang-Tidy</a></p>\n","group":"L2","line":1189},{"id":"content/06_tools_build_debug/06_ci.md:9b97fcd99830986c:1","question":"<p>(L2, T) Когда clang-tidy должен быть advisory, а когда blocking?</p>\n","answer":"<p><strong>Ответ:</strong> High-confidence correctness checks могут блокировать; новые/шумные правила сначала advisory с измерением false positives.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/extra/clang-tidy/\">Clang-Tidy</a></p>\n","group":"L2","line":1195},{"id":"content/06_tools_build_debug/06_ci.md:026e2311addec195:1","question":"<p>(L3, S) Как выбрать обязательный набор clang-tidy checks для команды?</p>\n","answer":"<p><strong>Ответ:</strong> Выбирать по defect history, поддержке toolchain и signal/noise; документировать rationale и owner.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/extra/clang-tidy/\">Clang-Tidy</a></p>\n","group":"L3","line":1204},{"id":"content/06_tools_build_debug/06_ci.md:744f5334a3d2b8f3:1","question":"<p>(L3, D) Как внедрять clang-tidy в legacy-кодовую базу без “красного моря” ошибок?</p>\n","answer":"<p><strong>Ответ:</strong> Зафиксировать existing baseline, блокировать новые важные findings, исправлять legacy по приоритету.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/extra/clang-tidy/\">Clang-Tidy</a></p>\n","group":"L3","line":1210},{"id":"content/06_tools_build_debug/06_ci.md:62ebd0ebd9282d15:1","question":"<p>(L3, P) Как организовать baseline/suppressions для постепенного улучшения качества?</p>\n","answer":"<p><strong>Ответ:</strong> Стабильная baseline identity, узкие suppressions с owner/reason и регулярным пересмотром; не скрывать новые findings в старом шуме.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/extra/clang-tidy/\">Clang-Tidy</a></p>\n","group":"L3","line":1216},{"id":"content/06_tools_build_debug/06_ci.md:6cc788f9e5ecaec2:1","question":"<p>(L3, D) Почему clang-tidy может давать разные результаты при смене toolchain/flags?</p>\n","answer":"<p><strong>Ответ:</strong> Меняются AST, models, macros и implementation checks; version/config входят в анализируемое окружение.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/extra/clang-tidy/\">Clang-Tidy</a></p>\n","group":"L3","line":1222},{"id":"content/06_tools_build_debug/06_ci.md:31843af626c16995:1","question":"<p>(L3, S) Как разделять style rules и correctness rules?</p>\n","answer":"<p><strong>Ответ:</strong> Formatting оставить formatter, correctness checks отделить по gate/severity; субъективный стиль не должен маскировать bug reports.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/extra/clang-tidy/\">Clang-Tidy</a></p>\n","group":"L3","line":1228},{"id":"content/06_tools_build_debug/06_ci.md:b3b9ae372bfc8c1c:1","question":"<p>(L3, P) Как связать clang-tidy output с review process?</p>\n","answer":"<p><strong>Ответ:</strong> Публиковать file/line/check/message и воспроизводимую команду; reviewer оценивает root cause и diff, а не только число warnings.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/extra/clang-tidy/\">Clang-Tidy</a></p>\n","group":"L3","line":1234},{"id":"content/06_tools_build_debug/06_ci.md:c4ac9dfa2d361fa3:1","question":"<p>(L3, D) Как triage'ить тысячи старых замечаний clang-tidy?</p>\n","answer":"<p><strong>Ответ:</strong> Дедупликация, группировка по rule/root cause, severity и ownership; массовые mechanical fixes отдельно от logic changes.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/extra/clang-tidy/\">Clang-Tidy</a></p>\n","group":"L3","line":1240},{"id":"content/06_tools_build_debug/06_ci.md:bae73b43e75eba7f:1","question":"<p>(L3, S) Как измерять эффективность clang-tidy, а не просто “количество warning'ов”?</p>\n","answer":"<p><strong>Ответ:</strong> Измерять подтверждённые defects, false positives, fix time и feedback latency, а не raw warning count.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/extra/clang-tidy/\">Clang-Tidy</a></p>\n","group":"L3","line":1246},{"id":"content/06_tools_build_debug/06_ci.md:cf0438e1c061f288:1","question":"<p>(L3, P) Как запускать разные наборы проверок для PR и nightly?</p>\n","answer":"<p><strong>Ответ:</strong> Отдельные configs/check sets с общей version baseline; PR — быстрые checks, nightly — полный анализ с owners.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/extra/clang-tidy/\">Clang-Tidy</a></p>\n","group":"L3","line":1252},{"id":"content/06_tools_build_debug/06_ci.md:fea9370da96e6eaf:1","question":"<p>(L3, S) Как интегрировать clang-tidy с developer workflow, а не только с CI?</p>\n","answer":"<p><strong>Ответ:</strong> Одинаковый config/version в editor, локальном script и CI; быстрый reproduction path снижает friction.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/extra/clang-tidy/\">Clang-Tidy</a></p>\n","group":"L3","line":1258},{"id":"content/06_tools_build_debug/06_ci.md:3eb95fa084f45628:1","question":"<p>(L4, S) Как строить organizational policy по static checks для C/C++?</p>\n","answer":"<p><strong>Ответ:</strong> Базовый обязательный набор и product-specific extensions, versioned rollout и exception process с owner.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/extra/clang-tidy/\">Clang-Tidy</a></p>\n","group":"L4","line":1267},{"id":"content/06_tools_build_debug/06_ci.md:86ff9eb7e18df841:1","question":"<p>(L4, S) Как выбирать между строгим quality gate и постепенной миграцией?</p>\n","answer":"<p><strong>Ответ:</strong> Строгий gate подходит новым high-signal checks; legacy debt снижать постепенно без требования исправить всё сразу.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/extra/clang-tidy/\">Clang-Tidy</a></p>\n","group":"L4","line":1273},{"id":"content/06_tools_build_debug/06_ci.md:6e0d726d040c39b9:1","question":"<p>(L4, D) Как расследовать случаи, когда clang-tidy мешает velocity больше, чем помогает?</p>\n","answer":"<p><strong>Ответ:</strong> Измерить run time, false positives и rework, опросить concrete failure cases; убрать ineffective rules или настроить окружение.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/extra/clang-tidy/\">Clang-Tidy</a></p>\n","group":"L4","line":1279},{"id":"content/06_tools_build_debug/06_ci.md:1330c2c28b1d6ab0:1","question":"<p>(L4, S) Как формализовать ownership за quality rule set?</p>\n","answer":"<p><strong>Ответ:</strong> Назначить maintainers, review rule changes и срок пересмотра suppressions; конфигурация — versioned часть проекта.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/extra/clang-tidy/\">Clang-Tidy</a></p>\n","group":"L4","line":1285},{"id":"content/06_tools_build_debug/06_ci.md:2ae2952113a5388f:1","question":"<p>(L4, S) Как использовать clang-tidy как часть архитектурной дисциплины, а не только lint?</p>\n","answer":"<p><strong>Ответ:</strong> Проверять agreed ownership/API patterns подходящими checks, но архитектурные свойства дополнять review и runtime tests.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/extra/clang-tidy/\">Clang-Tidy</a></p>\n","group":"L4","line":1291},{"id":"content/06_tools_build_debug/06_ci.md:b394a6f88bf85719:1","question":"<p>(L1, T) Что такое clang-format?</p>\n","answer":"<p><strong>Ответ:</strong> Инструмент автоматического форматирования source code по конфигурации style.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/ClangFormat.html\">ClangFormat</a></p>\n","group":"L1","line":1302},{"id":"content/06_tools_build_debug/06_ci.md:274000bfa23d9044:1","question":"<p>(L1, T) Зачем нужен единый code style?</p>\n","answer":"<p><strong>Ответ:</strong> Уменьшает различия оформления и освобождает review для поведения и дизайна.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/ClangFormat.html\">ClangFormat</a></p>\n","group":"L1","line":1308},{"id":"content/06_tools_build_debug/06_ci.md:046813473f768a75:1","question":"<p>(L1, P) Как форматировать файл через clang-format?</p>\n","answer":"<p><strong>Ответ:</strong> <code>clang-format -i src/main.cpp</code>; сначала убедиться в версии и выбранной <code>.clang-format</code>.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/ClangFormat.html\">ClangFormat</a></p>\n","group":"L1","line":1314},{"id":"content/06_tools_build_debug/06_ci.md:f48ddbdfa17d50ad:1","question":"<p>(L1, T) Почему автоформатирование уменьшает шум в review?</p>\n","answer":"<p><strong>Ответ:</strong> Механические решения единообразны, а отдельные format commits не смешивают стиль с логикой.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/ClangFormat.html\">ClangFormat</a></p>\n","group":"L1","line":1320},{"id":"content/06_tools_build_debug/06_ci.md:62dffc3ea9370650:1","question":"<p>(L1, D) Почему “споры о стиле” лучше решать инструментом?</p>\n","answer":"<p><strong>Ответ:</strong> Согласованная конфигурация автоматически исполняет принятые правила, не требуя обсуждения каждого отступа.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/ClangFormat.html\">ClangFormat</a></p>\n","group":"L1","line":1326},{"id":"content/06_tools_build_debug/06_ci.md:0fc3ea49118c0f2d:1","question":"<p>(L2, T) Как настраивается <code>.clang-format</code>?</p>\n","answer":"<p><strong>Ответ:</strong> YAML с BasedOnStyle и overrides; доступные options зависят от версии formatter.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/ClangFormat.html\">ClangFormat</a></p>\n","group":"L2","line":1335},{"id":"content/06_tools_build_debug/06_ci.md:583669f171d35ba3:1","question":"<p>(L2, P) Как проверять форматирование в CI?</p>\n","answer":"<p><strong>Ответ:</strong> <code>clang-format --dry-run --Werror src/main.cpp</code> на выбранных файлах при поддержке версии; никакой записи в рабочее дерево не требуется.</p>\n<p><strong>Типичная ошибка:</strong> Запускать <code>clang-format -i</code> в CI и не проверять diff/exit status: job может остаться зелёным после изменения исходников.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/ClangFormat.html\">ClangFormat</a></p>\n","group":"L2","line":1341},{"id":"content/06_tools_build_debug/06_ci.md:dae39dd2a633139f:1","question":"<p>(L2, P) Как форматировать только измененные строки/файлы?</p>\n","answer":"<p><strong>Ответ:</strong> Передавать changed files либо применять git-clang-format/clang-format-diff; форматирование строк может затронуть соседний syntactic context.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/ClangFormat.html\">ClangFormat</a></p>\n","group":"L2","line":1349},{"id":"content/06_tools_build_debug/06_ci.md:23196728ca1d485d:1","question":"<p>(L2, D) Почему несогласованная версия clang-format ломает workflow команды?</p>\n","answer":"<p><strong>Ответ:</strong> Версии по-разному интерпретируют options и layout; закрепить единую версию в editor и CI.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/ClangFormat.html\">ClangFormat</a></p>\n","group":"L2","line":1355},{"id":"content/06_tools_build_debug/06_ci.md:07a45b96bf117525:1","question":"<p>(L2, T) Почему массовое reformatting-изменение опасно для blame/history?</p>\n","answer":"<p><strong>Ответ:</strong> Создаёт широкий diff и меняет line attribution; отдельный commit можно добавить в blame ignore revisions.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/ClangFormat.html\">ClangFormat</a></p>\n","group":"L2","line":1361},{"id":"content/06_tools_build_debug/06_ci.md:8567e5571def8d3c:1","question":"<p>(L2, S) Когда делать big-bang reformat, а когда gradual adoption?</p>\n","answer":"<p><strong>Ответ:</strong> Big-bang удобен при координированном коротком freeze; gradual adoption уменьшает разовый конфликт, но временно смешивает стиль.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/ClangFormat.html\">ClangFormat</a></p>\n","group":"L2","line":1367},{"id":"content/06_tools_build_debug/06_ci.md:2179082a6fd7c788:1","question":"<p>(L2, D) Почему форматирование не должно смешиваться с логическими изменениями?</p>\n","answer":"<p><strong>Ответ:</strong> Иначе reviewer труднее видит semantic change и переносит patch между branches.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/ClangFormat.html\">ClangFormat</a></p>\n","group":"L2","line":1373},{"id":"content/06_tools_build_debug/06_ci.md:e25ac452d8bcd240:1","question":"<p>(L2, P) Как встроить clang-format в pre-commit или editor integration?</p>\n","answer":"<p><strong>Ответ:</strong> Общий versioned script/hook и format-on-save; CI проверяет тем же инструментом, не полагаясь только на локальный hook.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/ClangFormat.html\">ClangFormat</a></p>\n","group":"L2","line":1379},{"id":"content/06_tools_build_debug/06_ci.md:b3283ffcd3ff2362:1","question":"<p>(L2, T) Какие ограничения у clang-format как style tool?</p>\n","answer":"<p><strong>Ответ:</strong> Не проверяет correctness, naming semantics и архитектуру; не все preferences выразимы настройками.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/ClangFormat.html\">ClangFormat</a></p>\n","group":"L2","line":1385},{"id":"content/06_tools_build_debug/06_ci.md:7cd93110315d34e4:1","question":"<p>(L2, D) Что делать, если tool форматирует “не так, как нравится”?</p>\n","answer":"<p><strong>Ответ:</strong> Проверить доступную option и договорённость команды; локальное исключение должно иметь конкретную причину, а не персональный вкус.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/ClangFormat.html\">ClangFormat</a></p>\n","group":"L2","line":1391},{"id":"content/06_tools_build_debug/06_ci.md:4f53774dd43506c8:1","question":"<p>(L3, S) Как внедрять clang-format в legacy-репозитории?</p>\n","answer":"<p><strong>Ответ:</strong> Определить scope/version, exclude vendored/generated code, выполнить отдельный mechanical rollout с документированной локальной командой.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/ClangFormat.html\">ClangFormat</a></p>\n","group":"L3","line":1400},{"id":"content/06_tools_build_debug/06_ci.md:640ee7f08a012d9c:1","question":"<p>(L3, D) Как избежать конфликтов между formatter, generated code и third-party code?</p>\n","answer":"<p><strong>Ответ:</strong> Явный allowlist/exclude paths и форматирование источника generator template вместо его outputs где уместно.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/ClangFormat.html\">ClangFormat</a></p>\n","group":"L3","line":1406},{"id":"content/06_tools_build_debug/06_ci.md:1593ca6bb797f638:1","question":"<p>(L3, P) Как отделить policy для internal code и external/vendored code?</p>\n","answer":"<p><strong>Ответ:</strong> Собственный config для internal paths; vendor snapshots сохранять по upstream policy, проверяя только свои изменения при необходимости.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/ClangFormat.html\">ClangFormat</a></p>\n","group":"L3","line":1412},{"id":"content/06_tools_build_debug/06_ci.md:7c2982f402a287b9:1","question":"<p>(L3, S) Как сделать style checks быстрыми и нераздражающими?</p>\n","answer":"<p><strong>Ответ:</strong> Проверять changed files, выдавать точную fix command и согласовать editor version с CI.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/ClangFormat.html\">ClangFormat</a></p>\n","group":"L3","line":1418},{"id":"content/06_tools_build_debug/06_ci.md:50784a11dbdd44db:1","question":"<p>(L3, D) Почему строгий format gate может неожиданно тормозить delivery?</p>\n","answer":"<p><strong>Ответ:</strong> Version drift, неправильный scope или format churn создают повторные failures без полезного качества.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/ClangFormat.html\">ClangFormat</a></p>\n","group":"L3","line":1424},{"id":"content/06_tools_build_debug/06_ci.md:1fdea534db56ae6a:1","question":"<p>(L3, S) Как минимизировать merge conflicts после массового форматирования?</p>\n","answer":"<p><strong>Ответ:</strong> Короткое окно rollout, отдельный commit и координация активных branches; заранее сообщить rebase strategy.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/ClangFormat.html\">ClangFormat</a></p>\n","group":"L3","line":1430},{"id":"content/06_tools_build_debug/06_ci.md:d1561167540733ad:1","question":"<p>(L3, P) Как организовать auto-format suggestions в CI/PR comments?</p>\n","answer":"<p><strong>Ответ:</strong> Генерировать downloadable patch или review suggestions с точным scope; запись/комментарии требуют соответствующих permissions.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/ClangFormat.html\">ClangFormat</a></p>\n","group":"L3","line":1436},{"id":"content/06_tools_build_debug/06_ci.md:0c2df05ec350bd95:1","question":"<p>(L3, D) Как выбирать стабильную версию formatter для команды?</p>\n","answer":"<p><strong>Ответ:</strong> Выбрать доступную всем supported version, проверить на representative code и обновлять отдельно от feature changes.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/ClangFormat.html\">ClangFormat</a></p>\n","group":"L3","line":1442},{"id":"content/06_tools_build_debug/06_ci.md:6568085018dcf30e:1","question":"<p>(L3, S) Как встроить style automation в редакторы и IDE команды?</p>\n","answer":"<p><strong>Ответ:</strong> Настроить путь к pinned executable и общий config; дать простой bootstrap, не оставлять каждому IDE default.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/ClangFormat.html\">ClangFormat</a></p>\n","group":"L3","line":1448},{"id":"content/06_tools_build_debug/06_ci.md:1b1e97a4765e78b9:1","question":"<p>(L3, S) Как отделять объективные formatting rules от спорных style preferences?</p>\n","answer":"<p><strong>Ответ:</strong> Фиксировать только поддерживаемые однозначные rules; disputed preferences решать как изменение конфигурации, не в каждом PR.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/ClangFormat.html\">ClangFormat</a></p>\n","group":"L3","line":1454},{"id":"content/06_tools_build_debug/06_ci.md:ce548776007af83f:1","question":"<p>(L4, S) Как формализовать style governance для нескольких C++ команд?</p>\n","answer":"<p><strong>Ответ:</strong> Небольшая группа owners, общий baseline, documented exceptions и versioned rollout для команд.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/ClangFormat.html\">ClangFormat</a></p>\n","group":"L4","line":1463},{"id":"content/06_tools_build_debug/06_ci.md:0d0596f749e7bac9:1","question":"<p>(L4, S) Как строить migration strategy на единый формат в большой кодовой базе?</p>\n","answer":"<p><strong>Ответ:</strong> Инвентаризация paths, pilot, mechanical commits и migration window; исключить third-party и generated outputs.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/ClangFormat.html\">ClangFormat</a></p>\n","group":"L4","line":1469},{"id":"content/06_tools_build_debug/06_ci.md:b53740f75f23f064:1","question":"<p>(L4, D) Как расследовать падение developer productivity из-за слишком жестких format checks?</p>\n","answer":"<p><strong>Ответ:</strong> Собрать частоту failures, время исправления и причины churn; проверить scope, version consistency и локальную интеграцию.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/ClangFormat.html\">ClangFormat</a></p>\n","group":"L4","line":1475},{"id":"content/06_tools_build_debug/06_ci.md:8be4c97493dac84a:1","question":"<p>(L4, S) Как связать formatter policy с code review culture?</p>\n","answer":"<p><strong>Ответ:</strong> Автоматизировать механическое оформление, а review направить на semantics, tests и maintainability.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/ClangFormat.html\">ClangFormat</a></p>\n","group":"L4","line":1481},{"id":"content/06_tools_build_debug/06_ci.md:dab2aa209ad3c923:1","question":"<p>(L4, S) Как избежать превращения formatting automation в бюрократический ритуал?</p>\n","answer":"<p><strong>Ответ:</strong> Измерять friction и полезность, не создавать ручные approvals для автоматических отступов; сохранять простую fix command.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/ClangFormat.html\">ClangFormat</a></p>\n","group":"L4","line":1487},{"id":"content/06_tools_build_debug/06_ci.md:d9fe2940faa50da0:1","question":"<p>(L1, T) Что такое static analysis?</p>\n","answer":"<p><strong>Ответ:</strong> Анализ кода без исполнения целевой программы с использованием syntax, types, control/data-flow models.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/ClangStaticAnalyzer.html\">Clang Static Analyzer</a>; <a href=\"https://clang.llvm.org/extra/clang-tidy/\">Clang-Tidy</a></p>\n","group":"L1","line":1498},{"id":"content/06_tools_build_debug/06_ci.md:121e0581ec1ccc72:1","question":"<p>(L1, T) Чем static analysis отличается от компиляции и тестов?</p>\n","answer":"<p><strong>Ответ:</strong> Compilation обеспечивает построение программы и diagnostics, tests проверяют executions, static analysis исследует возможные пути моделями.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/ClangStaticAnalyzer.html\">Clang Static Analyzer</a>; <a href=\"https://clang.llvm.org/extra/clang-tidy/\">Clang-Tidy</a></p>\n","group":"L1","line":1504},{"id":"content/06_tools_build_debug/06_ci.md:c768b7874969e76d:1","question":"<p>(L1, T) Какие типы ошибок может находить static analyzer?</p>\n","answer":"<p><strong>Ответ:</strong> Null dereference, use-after-free, leaks, uninitialized values и API misuse в пределах моделей инструмента.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/ClangStaticAnalyzer.html\">Clang Static Analyzer</a>; <a href=\"https://clang.llvm.org/extra/clang-tidy/\">Clang-Tidy</a></p>\n","group":"L1","line":1510},{"id":"content/06_tools_build_debug/06_ci.md:03f2c615fda2098c:1","question":"<p>(L1, T) Почему тесты не заменяют static analysis?</p>\n","answer":"<p><strong>Ответ:</strong> Tests покрывают лишь выбранные inputs/interleavings; analyzer может обнаружить paths, которые не были исполнены.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/ClangStaticAnalyzer.html\">Clang Static Analyzer</a>; <a href=\"https://clang.llvm.org/extra/clang-tidy/\">Clang-Tidy</a></p>\n","group":"L1","line":1516},{"id":"content/06_tools_build_debug/06_ci.md:8b3fda6b50e52a7d:1","question":"<p>(L1, P) Какие static analysis tools применимы к C/C++?</p>\n","answer":"<p><strong>Ответ:</strong> Clang Static Analyzer, clang-tidy, GCC analyzer и Cppcheck; выбирать по нужным defect classes и поддерживаемой среде.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/ClangStaticAnalyzer.html\">Clang Static Analyzer</a>; <a href=\"https://clang.llvm.org/extra/clang-tidy/\">Clang-Tidy</a></p>\n","group":"L1","line":1522},{"id":"content/06_tools_build_debug/06_ci.md:46a79b4aa83bcf6b:1","question":"<p>(L2, T) Чем static analysis отличается от linting?</p>\n","answer":"<p><strong>Ответ:</strong> Lint часто проверяет локальные patterns/style, static analysis может моделировать control/data flow; граница терминов размыта.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/ClangStaticAnalyzer.html\">Clang Static Analyzer</a>; <a href=\"https://clang.llvm.org/extra/clang-tidy/\">Clang-Tidy</a></p>\n","group":"L2","line":1531},{"id":"content/06_tools_build_debug/06_ci.md:ed837ef573a49770:1","question":"<p>(L2, D) Почему static analysis может находить баги в редко исполняемом коде?</p>\n","answer":"<p><strong>Ответ:</strong> Исследует модели путей, не требуя фактического запуска каждого branch.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/ClangStaticAnalyzer.html\">Clang Static Analyzer</a>; <a href=\"https://clang.llvm.org/extra/clang-tidy/\">Clang-Tidy</a></p>\n","group":"L2","line":1537},{"id":"content/06_tools_build_debug/06_ci.md:cd9db2be2d6a3089:1","question":"<p>(L2, D) Почему false positives — центральная проблема анализа?</p>\n","answer":"<p><strong>Ответ:</strong> Неисполняемые paths и неполные models дают ложные findings; шум снижает доверие и отнимает время review.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/ClangStaticAnalyzer.html\">Clang Static Analyzer</a>; <a href=\"https://clang.llvm.org/extra/clang-tidy/\">Clang-Tidy</a></p>\n","group":"L2","line":1543},{"id":"content/06_tools_build_debug/06_ci.md:3a61ebb88cbcbc23:1","question":"<p>(L2, T) Какие классы дефектов особенно важны для C/C++?</p>\n","answer":"<p><strong>Ответ:</strong> Memory lifetime, bounds, initialization, integer errors, concurrency и unsafe API use; инструменты покрывают их неодинаково.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/ClangStaticAnalyzer.html\">Clang Static Analyzer</a>; <a href=\"https://clang.llvm.org/extra/clang-tidy/\">Clang-Tidy</a></p>\n","group":"L2","line":1549},{"id":"content/06_tools_build_debug/06_ci.md:5cc9aba6165509e0:1","question":"<p>(L2, P) Как встроить static analysis в CI pipeline?</p>\n","answer":"<p><strong>Ответ:</strong> Собрать актуальные compile commands/generated inputs, запустить versioned analyzer и сохранить отчёт с выбранной gate policy.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/ClangStaticAnalyzer.html\">Clang Static Analyzer</a>; <a href=\"https://clang.llvm.org/extra/clang-tidy/\">Clang-Tidy</a></p>\n","group":"L2","line":1555},{"id":"content/06_tools_build_debug/06_ci.md:4ec8072964e7652d:1","question":"<p>(L2, D) Почему полный анализ на каждом commit может быть слишком дорогим?</p>\n","answer":"<p><strong>Ответ:</strong> Межпроцедурный анализ и полный набор configurations требуют значительных CPU/RAM; полезность и coverage надо измерять.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/ClangStaticAnalyzer.html\">Clang Static Analyzer</a>; <a href=\"https://clang.llvm.org/extra/clang-tidy/\">Clang-Tidy</a></p>\n","group":"L2","line":1561},{"id":"content/06_tools_build_debug/06_ci.md:f59391c7af8efe26:1","question":"<p>(L2, S) Как разделять quick checks и deep analysis?</p>\n","answer":"<p><strong>Ответ:</strong> PR — high-signal/diff-focused checks, nightly — broad deep analysis; не терять owner и сроки для scheduled findings.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/ClangStaticAnalyzer.html\">Clang Static Analyzer</a>; <a href=\"https://clang.llvm.org/extra/clang-tidy/\">Clang-Tidy</a></p>\n","group":"L2","line":1567},{"id":"content/06_tools_build_debug/06_ci.md:07ef9dded9dfd9c1:1","question":"<p>(L2, D) Почему static analysis tool без доверия команды быстро перестает использоваться?</p>\n","answer":"<p><strong>Ответ:</strong> Когда finding часто неверен или нерепродуцируем, его перестают проверять; нужны настройка и быстрая обратная связь.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/ClangStaticAnalyzer.html\">Clang Static Analyzer</a>; <a href=\"https://clang.llvm.org/extra/clang-tidy/\">Clang-Tidy</a></p>\n","group":"L2","line":1573},{"id":"content/06_tools_build_debug/06_ci.md:3fb633dd09e32487:1","question":"<p>(L2, T) Как quality findings должны попадать в инженерный workflow?</p>\n","answer":"<p><strong>Ответ:</strong> Каждый actionable finding получает owner, severity, reproducer и решение fix/suppress с причиной.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/ClangStaticAnalyzer.html\">Clang Static Analyzer</a>; <a href=\"https://clang.llvm.org/extra/clang-tidy/\">Clang-Tidy</a></p>\n","group":"L2","line":1579},{"id":"content/06_tools_build_debug/06_ci.md:16b378a91dc69a0b:1","question":"<p>(L2, D) Когда warning должен блокировать merge, а когда нет?</p>\n","answer":"<p><strong>Ответ:</strong> Новый подтверждаемый high-impact defect блокирует; noise/legacy требуют triage, а исключения — владельца и срока.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/ClangStaticAnalyzer.html\">Clang Static Analyzer</a>; <a href=\"https://clang.llvm.org/extra/clang-tidy/\">Clang-Tidy</a></p>\n","group":"L2","line":1585},{"id":"content/06_tools_build_debug/06_ci.md:0b87954c962aedd8:1","question":"<p>(L3, S) Как выбрать стек static analysis для C/C++ проекта?</p>\n","answer":"<p><strong>Ответ:</strong> По defect history, language/platform coverage, accuracy, integration cost и возможности локального воспроизведения.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/ClangStaticAnalyzer.html\">Clang Static Analyzer</a>; <a href=\"https://clang.llvm.org/extra/clang-tidy/\">Clang-Tidy</a></p>\n","group":"L3","line":1594},{"id":"content/06_tools_build_debug/06_ci.md:31b008ebc09051ff:1","question":"<p>(L3, D) Как внедрять static analysis в legacy-код с тысячами existing findings?</p>\n","answer":"<p><strong>Ответ:</strong> Baseline старых findings и no-new-defects gate; приоритизировать наиболее опасные recurring patterns.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/ClangStaticAnalyzer.html\">Clang Static Analyzer</a>; <a href=\"https://clang.llvm.org/extra/clang-tidy/\">Clang-Tidy</a></p>\n","group":"L3","line":1600},{"id":"content/06_tools_build_debug/06_ci.md:ff0a8589403b4c9e:1","question":"<p>(L3, P) Как использовать baseline, diff-only analysis и suppression policy?</p>\n","answer":"<p><strong>Ответ:</strong> Baseline фиксирует долг, diff scope ограничивает review, suppressions документируют конкретные исключения; не скрывать root-cause spread.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/ClangStaticAnalyzer.html\">Clang Static Analyzer</a>; <a href=\"https://clang.llvm.org/extra/clang-tidy/\">Clang-Tidy</a></p>\n","group":"L3","line":1606},{"id":"content/06_tools_build_debug/06_ci.md:f38a440cbcfa87d3:1","question":"<p>(L3, D) Как triage'ить важность findings: correctness, security, maintainability?</p>\n","answer":"<p><strong>Ответ:</strong> Оценивать достижимость, impact и вероятность, а не только category; security labels не заменяют техническую проверку.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/ClangStaticAnalyzer.html\">Clang Static Analyzer</a>; <a href=\"https://clang.llvm.org/extra/clang-tidy/\">Clang-Tidy</a></p>\n","group":"L3","line":1612},{"id":"content/06_tools_build_debug/06_ci.md:3a3ca690d6dde9c8:1","question":"<p>(L3, S) Как увязать static analysis, sanitizer builds и tests в единую quality модель?</p>\n","answer":"<p><strong>Ответ:</strong> Static analysis исследует модели, sanitizers — реальные executions с instrumentation, tests задают inputs и expected behavior.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/ClangStaticAnalyzer.html\">Clang Static Analyzer</a>; <a href=\"https://clang.llvm.org/extra/clang-tidy/\">Clang-Tidy</a></p>\n","group":"L3","line":1618},{"id":"content/06_tools_build_debug/06_ci.md:16d006242e3b1b22:1","question":"<p>(L3, D) Почему результаты анализа меняются при изменении compile flags/config?</p>\n","answer":"<p><strong>Ответ:</strong> Меняются включённые branches, types, macros и target ABI; вывод относится к конкретной конфигурации.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/ClangStaticAnalyzer.html\">Clang Static Analyzer</a>; <a href=\"https://clang.llvm.org/extra/clang-tidy/\">Clang-Tidy</a></p>\n","group":"L3","line":1624},{"id":"content/06_tools_build_debug/06_ci.md:44a92f53672c9346:1","question":"<p>(L3, S) Как измерять signal-to-noise ratio у анализатора?</p>\n","answer":"<p><strong>Ответ:</strong> Доля actionable/confirmed findings, false-positive rate и время triage; отдельно учитывать missed defects из incident history.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/ClangStaticAnalyzer.html\">Clang Static Analyzer</a>; <a href=\"https://clang.llvm.org/extra/clang-tidy/\">Clang-Tidy</a></p>\n","group":"L3","line":1630},{"id":"content/06_tools_build_debug/06_ci.md:6317651446dd98c8:1","question":"<p>(L3, D) Как расследовать “мы исправили warning, а баг остался”?</p>\n","answer":"<p><strong>Ответ:</strong> Проверить root cause и coverage: устранение syntax pattern могло убрать warning, сохранив нарушенный invariant.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/ClangStaticAnalyzer.html\">Clang Static Analyzer</a>; <a href=\"https://clang.llvm.org/extra/clang-tidy/\">Clang-Tidy</a></p>\n","group":"L3","line":1636},{"id":"content/06_tools_build_debug/06_ci.md:6403a543b7a1f39d:1","question":"<p>(L3, S) Как построить процесс ownership для suppressions и accepted risks?</p>\n","answer":"<p><strong>Ответ:</strong> Каждое исключение имеет scope, owner, rationale и review date; изменение surrounding code может потребовать повторной оценки.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/ClangStaticAnalyzer.html\">Clang Static Analyzer</a>; <a href=\"https://clang.llvm.org/extra/clang-tidy/\">Clang-Tidy</a></p>\n","group":"L3","line":1642},{"id":"content/06_tools_build_debug/06_ci.md:c912582218c7ca91:1","question":"<p>(L3, S) Когда static analysis должен быть частью release criteria?</p>\n","answer":"<p><strong>Ответ:</strong> Когда анализ покрывает существенные risks supported configurations, стабилен и имеет заранее определённые criteria/exception policy.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/ClangStaticAnalyzer.html\">Clang Static Analyzer</a>; <a href=\"https://clang.llvm.org/extra/clang-tidy/\">Clang-Tidy</a></p>\n","group":"L3","line":1648},{"id":"content/06_tools_build_debug/06_ci.md:d5b7bd23d70cb3cb:1","question":"<p>(L4, S) Как строить strategy code quality automation для нескольких C/C++ продуктов?</p>\n","answer":"<p><strong>Ответ:</strong> Общий baseline tooling и metrics, продуктовые risk extensions и владельцы правил/rollout.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/ClangStaticAnalyzer.html\">Clang Static Analyzer</a>; <a href=\"https://clang.llvm.org/extra/clang-tidy/\">Clang-Tidy</a></p>\n","group":"L4","line":1657},{"id":"content/06_tools_build_debug/06_ci.md:2dfd43d197d5be75:1","question":"<p>(L4, S) Как принимать решения между strict gating и risk-based governance?</p>\n","answer":"<p><strong>Ответ:</strong> Учитывать impact, signal quality и legacy debt; gate должен защищать от дефектов, а не от произвольного warning count.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/ClangStaticAnalyzer.html\">Clang Static Analyzer</a>; <a href=\"https://clang.llvm.org/extra/clang-tidy/\">Clang-Tidy</a></p>\n","group":"L4","line":1663},{"id":"content/06_tools_build_debug/06_ci.md:8d33abf3ea8120b2:1","question":"<p>(L4, D) Как расследовать ситуацию, когда quality tooling создает больше friction, чем пользы?</p>\n","answer":"<p><strong>Ответ:</strong> Измерить false positives, latency и repeated work; скорректировать scope/version/rules и проверить эффект пилотом.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/ClangStaticAnalyzer.html\">Clang Static Analyzer</a>; <a href=\"https://clang.llvm.org/extra/clang-tidy/\">Clang-Tidy</a></p>\n","group":"L4","line":1669},{"id":"content/06_tools_build_debug/06_ci.md:2c844616dc13d44e:1","question":"<p>(L4, S) Как сделать так, чтобы static analysis реально снижал defect rate?</p>\n","answer":"<p><strong>Ответ:</strong> Связать checks с реальными incidents, поддерживать rules и regression tests, измерять подтверждённые предотвращённые дефекты.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/ClangStaticAnalyzer.html\">Clang Static Analyzer</a>; <a href=\"https://clang.llvm.org/extra/clang-tidy/\">Clang-Tidy</a></p>\n","group":"L4","line":1675},{"id":"content/06_tools_build_debug/06_ci.md:67077daa29782398:1","question":"<p>(L4, S) Как встроить code quality automation в инженерную культуру, а не только в CI config?</p>\n","answer":"<p><strong>Ответ:</strong> Дать одинаковые локальные команды, explainable findings и accountable owners; обсуждать root cause, а не цвет job.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/ClangStaticAnalyzer.html\">Clang Static Analyzer</a>; <a href=\"https://clang.llvm.org/extra/clang-tidy/\">Clang-Tidy</a></p>\n<hr />\n","group":"L4","line":1681},{"id":"content/06_tools_build_debug/06_ci.md:b277f475287ca3b7:1","question":"<p>(L2, D) Локально проект собирается, а в CI падает на этапе configure/build. Какие типовые причины проверишь?</p>\n","answer":"<p><strong>Ответ:</strong> Toolchain/dependency versions, CMake cache, generated files, flags, paths/case sensitivity и доступ к package registry.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.github.com/en/actions\">GitHub Actions documentation</a>; <a href=\"https://clang.llvm.org/extra/clang-tidy/\">Clang-Tidy</a></p>\n","group":"L2","line":1694},{"id":"content/06_tools_build_debug/06_ci.md:59a0f02e21f1eb5f:1","question":"<p>(L2, D) Тесты нестабильны только в CI. Какие первые гипотезы?</p>\n","answer":"<p><strong>Ответ:</strong> CPU pressure, races, sleeps/timeouts, test order, shared resources и network; сохранить seed и runtime environment.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.github.com/en/actions\">GitHub Actions documentation</a>; <a href=\"https://clang.llvm.org/extra/clang-tidy/\">Clang-Tidy</a></p>\n","group":"L2","line":1700},{"id":"content/06_tools_build_debug/06_ci.md:06827570bdc5d097:1","question":"<p>(L2, D) Pipeline стал вдвое медленнее после добавления quality checks. Как разбирать?</p>\n","answer":"<p><strong>Ответ:</strong> Разбить duration по checks, setup и очереди; устранить повторные parses/builds, parallelize и перенести действительно дорогие checks в schedule.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.github.com/en/actions\">GitHub Actions documentation</a>; <a href=\"https://clang.llvm.org/extra/clang-tidy/\">Clang-Tidy</a></p>\n","group":"L2","line":1706},{"id":"content/06_tools_build_debug/06_ci.md:940d04cb2996857a:1","question":"<p>(L2, D) После включения cache сборка ускорилась, но иногда появляются “странные” ошибки. Какие причины?</p>\n","answer":"<p><strong>Ответ:</strong> Неполные keys, смешанные configs, stale build tree и untrusted cache writes; сравнить clean run и hashes.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.github.com/en/actions\">GitHub Actions documentation</a>; <a href=\"https://clang.llvm.org/extra/clang-tidy/\">Clang-Tidy</a></p>\n","group":"L2","line":1712},{"id":"content/06_tools_build_debug/06_ci.md:1350b4056ff99a15:1","question":"<p>(L2, D) clang-format/clang-tidy падают только на runner'е, а локально нет. Что проверять?</p>\n","answer":"<p><strong>Ответ:</strong> Executable version, config discovery, working directory, compile commands и generated includes; воспроизвести точную CI command.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.github.com/en/actions\">GitHub Actions documentation</a>; <a href=\"https://clang.llvm.org/extra/clang-tidy/\">Clang-Tidy</a></p>\n","group":"L2","line":1718},{"id":"content/06_tools_build_debug/06_ci.md:3eb7f1adce731b83:1","question":"<p>(L3, D) После обновления compiler image часть pipeline'ов стала красной. Как строить расследование?</p>\n","answer":"<p><strong>Ответ:</strong> Зафиксировать old/new digests и diagnostics, проверить минимальный reproducer; разделить реальные defects и toolchain/config regression.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.github.com/en/actions\">GitHub Actions documentation</a>; <a href=\"https://clang.llvm.org/extra/clang-tidy/\">Clang-Tidy</a></p>\n","group":"L3","line":1727},{"id":"content/06_tools_build_debug/06_ci.md:85d17f7b838c5270:1","question":"<p>(L3, D) GitHub Actions/GitLab CI/Jenkins дают разные результаты на одном и том же проекте. Какие категории причин рассмотрешь?</p>\n","answer":"<p><strong>Ответ:</strong> Различия source checkout/submodules, image, shell/env, permissions, dependency resolution, parallelism и artifacts.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.github.com/en/actions\">GitHub Actions documentation</a>; <a href=\"https://clang.llvm.org/extra/clang-tidy/\">Clang-Tidy</a></p>\n","group":"L3","line":1733},{"id":"content/06_tools_build_debug/06_ci.md:081419537c477bc6:1","question":"<p>(L3, D) Из-за большого числа legacy warning'ов команда игнорирует новые quality findings. Как исправлять процесс?</p>\n","answer":"<p><strong>Ответ:</strong> Зафиксировать baseline, показывать отдельно новые findings, назначить legacy owners и включить проверенные high-signal gates.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.github.com/en/actions\">GitHub Actions documentation</a>; <a href=\"https://clang.llvm.org/extra/clang-tidy/\">Clang-Tidy</a></p>\n","group":"L3","line":1739},{"id":"content/06_tools_build_debug/06_ci.md:7069638946954a90:1","question":"<p>(L3, D) Build artifacts из одного stage переиспользуются дальше, но иногда тесты проходят на “не тех” бинарях. Что проверять?</p>\n","answer":"<p><strong>Ответ:</strong> Artifact run/commit identity, names, download scope, stale paths и implicit rebuild; сравнить hashes реально запущенных binaries.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.github.com/en/actions\">GitHub Actions documentation</a>; <a href=\"https://clang.llvm.org/extra/clang-tidy/\">Clang-Tidy</a></p>\n","group":"L3","line":1745},{"id":"content/06_tools_build_debug/06_ci.md:42080a310a2483c2:1","question":"<p>(L3, D) CI green, но production defect rate не снижается. Какие изъяны в quality automation возможны?</p>\n","answer":"<p><strong>Ответ:</strong> Слабый workload coverage, отсутствующие integration/failure tests, ignored reports и gates, не соответствующие реальным defect classes.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.github.com/en/actions\">GitHub Actions documentation</a>; <a href=\"https://clang.llvm.org/extra/clang-tidy/\">Clang-Tidy</a></p>\n","group":"L3","line":1751},{"id":"content/06_tools_build_debug/06_ci.md:bd1e5fe67fdbf485:1","question":"<p>(L4, S) Как спроектировать CI/CD и automation strategy для C/C++ организации с несколькими командами и разными репозиториями?</p>\n","answer":"<p><strong>Ответ:</strong> Общая platform contract, managed toolchains/templates и artifact identity, а продуктовые gates определяются рисками и поддерживаемыми targets.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.github.com/en/actions\">GitHub Actions documentation</a>; <a href=\"https://clang.llvm.org/extra/clang-tidy/\">Clang-Tidy</a></p>\n","group":"L4","line":1760},{"id":"content/06_tools_build_debug/06_ci.md:205fd73db4456f56:1","question":"<p>(L4, S) Какие проверки должны быть обязательными на PR, какие — nightly, а какие — release-only?</p>\n","answer":"<p><strong>Ответ:</strong> PR — быстрые correctness/build gates; nightly — stress/full matrix/deep analysis; release — exact artifact и compatibility validation.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.github.com/en/actions\">GitHub Actions documentation</a>; <a href=\"https://clang.llvm.org/extra/clang-tidy/\">Clang-Tidy</a></p>\n","group":"L4","line":1766},{"id":"content/06_tools_build_debug/06_ci.md:8e800bf08728eedb:1","question":"<p>(L4, S) Как уменьшить стоимость и время pipeline без потери инженерной строгости?</p>\n","answer":"<p><strong>Ответ:</strong> Оптимизировать critical path, caching и redundant work, сохраняя проверяемые inputs и coverage; измерять эффект и clean-build reliability.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.github.com/en/actions\">GitHub Actions documentation</a>; <a href=\"https://clang.llvm.org/extra/clang-tidy/\">Clang-Tidy</a></p>\n","group":"L4","line":1772},{"id":"content/06_tools_build_debug/06_ci.md:f1e6f111c9cd62dc:1","question":"<p>(L4, S) Как формализовать ownership за CI templates, runners, quality rules и suppressions?</p>\n","answer":"<p><strong>Ответ:</strong> Назначить platform owners для runners/templates и product owners для rules/findings; исключения документировать и пересматривать.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.github.com/en/actions\">GitHub Actions documentation</a>; <a href=\"https://clang.llvm.org/extra/clang-tidy/\">Clang-Tidy</a></p>\n","group":"L4","line":1778},{"id":"content/06_tools_build_debug/06_ci.md:9f0a73d52b34ad62:1","question":"<p>(L4, S) Как выстроить культуру, где CI/CD — это инструмент доказательного качества, а не просто “красно-зеленая лампочка”?</p>\n","answer":"<p><strong>Ответ:</strong> Сохранять reproducible evidence, исправлять recurring failure causes и связывать checks с defect history/SLO, а не только pass rate.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.github.com/en/actions\">GitHub Actions documentation</a>; <a href=\"https://clang.llvm.org/extra/clang-tidy/\">Clang-Tidy</a></p>\n<hr />\n","group":"L4","line":1784}];
